  define(["core/services/audit"], function (module, exports, require) {
'use strict';

const db = require('../db');
const { nowStamp } = require('../util/dates');

function log(user, action, entity, entityId, detail) {
  db.get().prepare(`INSERT INTO audit_log (at, user_id, username, action, entity, entity_id, detail)
                    VALUES (?, ?, ?, ?, ?, ?, ?)`)
    .run(nowStamp(), user?.id ?? null, user?.username ?? 'system', action, entity ?? null,
      entityId === undefined || entityId === null ? null : String(entityId),
      detail ? (typeof detail === 'string' ? detail : JSON.stringify(detail)) : null);
}

function list({ from, to, limit = 300 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('at >= ?'); args.push(`${from} 00:00:00`); }
  if (to) { where.push('at <= ?'); args.push(`${to} 23:59:59`); }
  const sql = `SELECT * FROM audit_log ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
               ORDER BY id DESC LIMIT ?`;
  return db.get().prepare(sql).all(...args, Math.min(Number(limit) || 300, 2000));
}

module.exports = { log, list };

});

  define(["core/services/auth"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const { assert, fail } = require('../util/errors');
const v = require('../util/validate');
const { nowStamp } = require('../util/dates');

const ROLES = ['admin', 'pharmacist', 'cashier'];

/**
 * PBKDF2-HMAC-SHA256, implemented so it produces the same bytes in Node and in
 * a browser — a database made by the web build still accepts the same passwords
 * in the desktop build. Nothing leaves this computer either way.
 */
const { hashPassword, verifyPassword } = require('../util/hash');

function publicUser(row) {
  if (!row) return null;
  return { id: row.id, username: row.username, name: row.name, role: row.role, active: !!row.active };
}

function login({ username, password }) {
  const uname = v.str(username, 'Username', { required: true, max: 40 }).toLowerCase();
  assert(String(password ?? '').length > 0, 'Password is required.');
  const row = db.get().prepare('SELECT * FROM users WHERE lower(username) = ?').get(uname);
  if (!row || !row.active || !verifyPassword(password, row.pass_hash, row.pass_salt)) {
    fail('Incorrect username or password.', 'AUTH_FAILED');
  }
  audit.log(row, 'login', 'user', row.id);
  return publicUser(row);
}

function list() {
  return db.get().prepare('SELECT * FROM users ORDER BY role, name').all().map(publicUser);
}

function create(actor, payload) {
  requireAdmin(actor);
  const username = v.str(payload.username, 'Username', { required: true, max: 40, min: 3 }).toLowerCase();
  assert(/^[a-z0-9._-]+$/.test(username), 'Username may use letters, numbers, dot, dash and underscore only.');
  const name = v.str(payload.name, 'Full name', { required: true, max: 80 });
  const role = v.oneOf(payload.role, 'Role', ROLES, 'cashier');
  const password = String(payload.password ?? '');
  assert(password.length >= 4, 'Password must be at least 4 characters.');
  const exists = db.get().prepare('SELECT id FROM users WHERE lower(username) = ?').get(username);
  assert(!exists, 'That username is already taken.');
  const { hash, salt } = hashPassword(password);
  const info = db.get().prepare(`INSERT INTO users (username, name, role, pass_hash, pass_salt, active, created_at)
                                 VALUES (?, ?, ?, ?, ?, 1, ?)`).run(username, name, role, hash, salt, nowStamp());
  audit.log(actor, 'user.create', 'user', info.lastInsertRowid, { username, role });
  return publicUser(db.get().prepare('SELECT * FROM users WHERE id = ?').get(info.lastInsertRowid));
}

function update(actor, payload) {
  requireAdmin(actor);
  const id = v.integer(payload.id, 'User', { required: true, min: 1 });
  const row = db.get().prepare('SELECT * FROM users WHERE id = ?').get(id);
  assert(row, 'That user no longer exists.');
  const name = v.str(payload.name, 'Full name', { required: true, max: 80 });
  const role = v.oneOf(payload.role, 'Role', ROLES, row.role);
  const active = v.bool(payload.active);
  if (row.role === 'admin' && (role !== 'admin' || !active)) {
    const admins = db.get().prepare("SELECT COUNT(*) AS n FROM users WHERE role = 'admin' AND active = 1 AND id <> ?").get(id).n;
    assert(admins > 0, 'At least one active administrator must remain.');
  }
  db.get().prepare('UPDATE users SET name = ?, role = ?, active = ? WHERE id = ?').run(name, role, active, id);
  if (payload.password) {
    assert(String(payload.password).length >= 4, 'Password must be at least 4 characters.');
    const { hash, salt } = hashPassword(payload.password);
    db.get().prepare('UPDATE users SET pass_hash = ?, pass_salt = ? WHERE id = ?').run(hash, salt, id);
  }
  audit.log(actor, 'user.update', 'user', id, { name, role, active });
  return publicUser(db.get().prepare('SELECT * FROM users WHERE id = ?').get(id));
}

function changePassword(actor, { currentPassword, newPassword }) {
  assert(actor?.id, 'You must be signed in.');
  const row = db.get().prepare('SELECT * FROM users WHERE id = ?').get(actor.id);
  assert(row, 'That user no longer exists.');
  assert(verifyPassword(String(currentPassword ?? ''), row.pass_hash, row.pass_salt), 'Current password is incorrect.');
  assert(String(newPassword ?? '').length >= 4, 'New password must be at least 4 characters.');
  const { hash, salt } = hashPassword(newPassword);
  db.get().prepare('UPDATE users SET pass_hash = ?, pass_salt = ? WHERE id = ?').run(hash, salt, actor.id);
  audit.log(actor, 'user.password', 'user', actor.id);
  return { ok: true };
}

/** Used by the setup wizard to replace the default admin credentials. */
function setAdminPassword(password) {
  assert(String(password ?? '').length >= 4, 'Password must be at least 4 characters.');
  const row = db.get().prepare("SELECT * FROM users WHERE role = 'admin' ORDER BY id LIMIT 1").get();
  assert(row, 'No administrator account exists.');
  const { hash, salt } = hashPassword(password);
  db.get().prepare('UPDATE users SET pass_hash = ?, pass_salt = ? WHERE id = ?').run(hash, salt, row.id);
  return publicUser(row);
}

function requireAdmin(actor) {
  assert(actor && actor.role === 'admin', 'Only an administrator can do that.', 'FORBIDDEN');
}

function requireRole(actor, roles) {
  assert(actor && roles.includes(actor.role), 'You do not have permission for that action.', 'FORBIDDEN');
}

function remove(actor, { id }) {
  requireAdmin(actor);
  const uid = v.integer(id, 'User', { required: true, min: 1 });
  assert(uid !== actor.id, 'You cannot delete the account you are signed in with.');
  const row = db.get().prepare('SELECT * FROM users WHERE id = ?').get(uid);
  assert(row, 'That user no longer exists.');
  if (row.role === 'admin') {
    const admins = db.get().prepare("SELECT COUNT(*) AS n FROM users WHERE role = 'admin' AND active = 1 AND id <> ?").get(uid).n;
    assert(admins > 0, 'At least one active administrator must remain.');
  }
  db.get().prepare('UPDATE users SET active = 0 WHERE id = ?').run(uid);
  audit.log(actor, 'user.deactivate', 'user', uid);
  return { ok: true };
}

module.exports = {
  ROLES, hashPassword, verifyPassword, login, list, create, update, remove,
  changePassword, setAdminPassword, requireAdmin, requireRole, publicUser
};

});

  define(["core/services/backup.web","core/services/backup"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const settings = require('./settings');
const paths = require('../paths');
const { assert, fail } = require('../util/errors');
const { nowStamp, today } = require('../util/dates');
const { createDatabase } = require('../db/sqljs');

/**
 * Backup and restore for the web build. A backup is the real SQLite file —
 * the same bytes the desktop build writes — so the two can swap databases.
 *
 * `targetPath` / `sourcePath` are handled by the page's bridge, which turns
 * them into a download and a file picker; the service itself only deals in bytes.
 */
const pending = { downloads: new Map(), uploads: new Map() };

function suggestedName() {
  return `MedBillPro_Backup_${today()}.db`;
}

/** Produces the backup bytes and hands them to the bridge to save. */
async function create(actor, { targetPath = null } = {}) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  await db.persist();
  const bytes = db.exportBytes();
  const name = targetPath || suggestedName();
  pending.downloads.set(name, bytes);
  settings.put('last_backup_at', nowStamp());
  audit.log(actor, 'backup.create', 'backup', null, { name, size: bytes.length });
  return { path: name, name, size: bytes.length, at: nowStamp(), download: true };
}

/** Keeps a few automatic copies inside browser storage. */
async function auto(reason = 'auto') {
  const snap = await db.addSnapshot(reason);
  settings.put('last_backup_at', nowStamp());
  return { path: snap.name, size: snap.size };
}

async function list() {
  const snaps = await db.snapshots();
  return snaps.map((s) => ({
    name: s.name,
    path: `snapshot:${s.name}`,
    size: s.size,
    modified: s.at,
    kind: 'auto'
  }));
}

function bytesFor(sourcePath) {
  if (typeof sourcePath === 'string' && sourcePath.startsWith('snapshot:')) return null; // resolved in restore()
  const uploaded = pending.uploads.get(sourcePath);
  assert(uploaded, 'Choose a backup file first.');
  return uploaded;
}

/** Reads a candidate file and reports whether it is one of our databases. */
async function inspect({ sourcePath, bytes = null }) {
  let data = bytes;
  if (!data) {
    if (typeof sourcePath === 'string' && sourcePath.startsWith('snapshot:')) {
      const snaps = await db.snapshots();
      const found = snaps.find((s) => `snapshot:${s.name}` === sourcePath);
      assert(found, 'That automatic backup is no longer stored.');
      data = found.bytes;
    } else {
      data = bytesFor(sourcePath);
    }
  }
  let probe = null;
  try {
    probe = createDatabase(db.getSQL(), new Uint8Array(data));
    const tables = probe.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all().map((r) => r.name);
    const required = ['settings', 'products', 'batches', 'sales', 'sale_items'];
    const missing = required.filter((t) => !tables.includes(t));
    assert(missing.length === 0, `That file is not a MedV backup (missing: ${missing.join(', ')}).`);
    const counts = {
      products: probe.prepare('SELECT COUNT(*) AS n FROM products').get().n,
      sales: probe.prepare('SELECT COUNT(*) AS n FROM sales').get().n,
      customers: probe.prepare('SELECT COUNT(*) AS n FROM customers').get().n
    };
    const storeName = probe.prepare("SELECT value FROM settings WHERE key = 'store_name'").get()?.value ?? '';
    const lastSale = probe.prepare('SELECT MAX(date) AS d FROM sales').get().d;
    return {
      path: sourcePath,
      size: data.length,
      modified: new Date().toISOString(),
      version: probe.pragma('user_version', { simple: true }),
      counts,
      storeName,
      lastSale
    };
  } catch (err) {
    if (err.expected) throw err;
    fail('That file could not be opened as a database. It may be damaged or not a backup file.', 'BAD_BACKUP');
  } finally {
    try { probe?.close(); } catch { /* ignore */ }
  }
  return null;
}

/** Replaces the live database, keeping a copy of the present one first. */
async function restore(actor, { sourcePath, bytes = null, confirm = false }) {
  auth.requireRole(actor, ['admin']);
  let data = bytes;
  if (!data) {
    if (typeof sourcePath === 'string' && sourcePath.startsWith('snapshot:')) {
      const snaps = await db.snapshots();
      const found = snaps.find((s) => `snapshot:${s.name}` === sourcePath);
      assert(found, 'That automatic backup is no longer stored.');
      data = found.bytes;
    } else {
      data = bytesFor(sourcePath);
    }
  }
  const info = await inspect({ sourcePath, bytes: data });
  assert(confirm === true, 'Restoring replaces all current data. Please confirm to continue.', 'CONFIRM_REQUIRED');

  const safety = await db.addSnapshot('before-restore');
  audit.log(actor, 'backup.restore.start', 'backup', null, { sourcePath, safety: safety.name });
  const migration = await db.replaceWith(data);
  audit.log(actor, 'backup.restore.done', 'backup', null, { sourcePath, safety: safety.name });
  return { ok: true, restoredFrom: sourcePath, safetyCopy: `snapshot:${safety.name}`, info, db: migration };
}

async function status() {
  const size = db.isOpen() ? db.exportBytes().length : 0;
  const last = settings.get('last_backup_at');
  const days = Number(settings.get('backup_reminder_days', '7')) || 7;
  const overdue = !last || (Date.now() - Date.parse(last.replace(' ', 'T'))) > days * 86400000;
  const stored = await list();
  const space = await db.idb.estimate();
  return {
    paths: paths.paths(),
    dbSize: size,
    lastBackupAt: last,
    backups: stored,
    count: stored.length,
    overdue,
    browser: true,
    storage: space
  };
}

/** Wipes transactions but keeps masters — used by "clear test data". */
function clearTransactions(actor, { confirm = false, keepMasters = true }) {
  auth.requireRole(actor, ['admin']);
  assert(confirm === true, 'Please confirm before clearing data.', 'CONFIRM_REQUIRED');
  return db.tx(() => {
    const conn = db.get();
    // Children before parents — foreign keys stay enforced throughout.
    const tables = ['payments', 'doctor_commissions', 'rx_reminders', 'stock_adjustments',
      'sale_return_items', 'sale_returns', 'purchase_return_items', 'purchase_returns',
      'sale_items', 'sales', 'purchase_items', 'purchases', 'expenses', 'ledger'];
    for (const t of tables) conn.prepare(`DELETE FROM ${t}`).run();
    conn.prepare('UPDATE batches SET qty_units = 0').run();
    if (!keepMasters) {
      for (const t of ['batches', 'products', 'customers', 'doctors', 'suppliers']) conn.prepare(`DELETE FROM ${t}`).run();
    }
    conn.prepare('UPDATE counters SET value = 0').run();
    audit.log(actor, 'data.clear', 'database', null, { keepMasters });
    return { ok: true };
  });
}

module.exports = { create, auto, list, inspect, restore, status, clearTransactions, suggestedName, pending };

});

  define(["core/services/gst"], function (module, exports, require) {
'use strict';

const db = require('../db');
const settings = require('./settings');
const { r2 } = require('../util/money');
const { today, monthStart, monthEnd, financialYear } = require('../util/dates');

function range({ from, to, month } = {}) {
  if (month) return { from: `${month}-01`, to: monthEnd(`${month}-01`) };
  return { from: from || monthStart(today()), to: to || monthEnd(today()) };
}

function emptyRate(rate) {
  return { rate, taxable: 0, cgst: 0, sgst: 0, igst: 0, total: 0, invoices: 0 };
}

function addRate(bucket, row) {
  bucket.taxable = r2(bucket.taxable + row.taxable);
  bucket.cgst = r2(bucket.cgst + row.cgst);
  bucket.sgst = r2(bucket.sgst + row.sgst);
  bucket.igst = r2(bucket.igst + (row.igst || 0));
  bucket.total = r2(bucket.taxable + bucket.cgst + bucket.sgst + bucket.igst);
  return bucket;
}

/** GSTR-1 — outward supplies (sales), split B2B / B2C with an HSN summary. */
function gstr1(params = {}) {
  const { from, to } = range(params);
  const conn = db.get();
  const lines = conn.prepare(`SELECT si.*, s.no, s.date, s.inter_state, s.customer_id,
      c.name AS customer_name, c.gstin AS customer_gstin
    FROM sale_items si JOIN sales s ON s.id = si.sale_id
    LEFT JOIN customers c ON c.id = s.customer_id
    WHERE s.date >= ? AND s.date <= ? ORDER BY s.date, s.id`).all(from, to);

  const returns = conn.prepare(`SELECT ri.*, r.no, r.date FROM sale_return_items ri
    JOIN sale_returns r ON r.id = ri.return_id WHERE r.date >= ? AND r.date <= ?`).all(from, to);

  const b2bMap = new Map();
  const b2cRates = new Map();
  const hsnMap = new Map();
  const invoiceSet = new Set();

  for (const l of lines) {
    invoiceSet.add(l.no);
    const rateKey = String(l.gst_rate);
    if (l.customer_gstin) {
      const key = `${l.customer_gstin}|${l.no}`;
      const entry = b2bMap.get(key) || {
        gstin: l.customer_gstin, customer: l.customer_name, invoice: l.no, date: l.date,
        inter_state: !!l.inter_state, taxable: 0, cgst: 0, sgst: 0, igst: 0, total: 0, rates: new Set()
      };
      entry.rates.add(l.gst_rate);
      addRate(entry, l);
      b2bMap.set(key, entry);
    } else {
      const bucket = b2cRates.get(rateKey) || emptyRate(l.gst_rate);
      addRate(bucket, l);
      b2cRates.set(rateKey, bucket);
    }
    const hsnKey = `${l.hsn || '-'}|${l.gst_rate}`;
    const hsn = hsnMap.get(hsnKey) || { hsn: l.hsn || '-', rate: l.gst_rate, qty: 0, taxable: 0, cgst: 0, sgst: 0, igst: 0, total: 0 };
    hsn.qty += l.qty_units;
    addRate(hsn, l);
    hsnMap.set(hsnKey, hsn);
  }

  const creditNotes = new Map();
  for (const r of returns) {
    const key = String(r.gst_rate);
    const bucket = creditNotes.get(key) || emptyRate(r.gst_rate);
    const half = r2(r.gst_amount / 2);
    addRate(bucket, { taxable: r.taxable, cgst: half, sgst: r2(r.gst_amount - half), igst: 0 });
    creditNotes.set(key, bucket);
  }

  const b2b = [...b2bMap.values()].map((e) => ({ ...e, rates: [...e.rates].sort((a, b) => a - b) }));
  const b2c = [...b2cRates.values()].sort((a, b) => a.rate - b.rate);
  const cn = [...creditNotes.values()].sort((a, b) => a.rate - b.rate);
  const totals = [...b2b, ...b2c].reduce((a, r) => addRate(a, r), emptyRate('all'));
  const cnTotals = cn.reduce((a, r) => addRate(a, r), emptyRate('all'));

  return {
    period: { from, to },
    store: settings.storeProfile(),
    invoiceCount: invoiceSet.size,
    b2b,
    b2c,
    creditNotes: cn,
    hsn: [...hsnMap.values()].sort((a, b) => b.taxable - a.taxable),
    totals,
    creditNoteTotals: cnTotals,
    net: {
      taxable: r2(totals.taxable - cnTotals.taxable),
      cgst: r2(totals.cgst - cnTotals.cgst),
      sgst: r2(totals.sgst - cnTotals.sgst),
      igst: r2(totals.igst - cnTotals.igst),
      total: r2(totals.total - cnTotals.total)
    }
  };
}

/** GSTR-2 — inward supplies (purchases) grouped by supplier, with ITC. */
function gstr2(params = {}) {
  const { from, to } = range(params);
  const conn = db.get();
  const rows = conn.prepare(`SELECT p.id, p.no, p.ref_no, p.date, p.inter_state, p.subtotal, p.gst_amount, p.total,
      s.name AS supplier_name, s.gstin AS supplier_gstin
    FROM purchases p LEFT JOIN suppliers s ON s.id = p.supplier_id
    WHERE p.date >= ? AND p.date <= ? ORDER BY p.date, p.id`).all(from, to);

  const byRate = new Map();
  const rateRows = conn.prepare(`SELECT pi.gst_rate, SUM(pi.taxable) AS taxable, SUM(pi.gst_amount) AS gst
    FROM purchase_items pi JOIN purchases p ON p.id = pi.purchase_id
    WHERE p.date >= ? AND p.date <= ? GROUP BY pi.gst_rate`).all(from, to);
  for (const r of rateRows) {
    const half = r2(r.gst / 2);
    byRate.set(String(r.gst_rate), addRate(emptyRate(r.gst_rate), { taxable: r.taxable, cgst: half, sgst: r2(r.gst - half), igst: 0 }));
  }

  const debitNotes = conn.prepare(`SELECT ri.gst_rate, SUM(ri.taxable) AS taxable, SUM(ri.gst_amount) AS gst
    FROM purchase_return_items ri JOIN purchase_returns r ON r.id = ri.return_id
    WHERE r.date >= ? AND r.date <= ? GROUP BY ri.gst_rate`).all(from, to);

  const totals = rows.reduce((a, r) => ({
    taxable: r2(a.taxable + r.subtotal),
    gst: r2(a.gst + r.gst_amount),
    total: r2(a.total + r.total)
  }), { taxable: 0, gst: 0, total: 0 });
  const dnTotals = debitNotes.reduce((a, r) => ({ taxable: r2(a.taxable + r.taxable), gst: r2(a.gst + r.gst) }), { taxable: 0, gst: 0 });

  const withoutGstin = rows.filter((r) => !r.supplier_gstin);
  return {
    period: { from, to },
    store: settings.storeProfile(),
    rows,
    byRate: [...byRate.values()].sort((a, b) => a.rate - b.rate),
    debitNotes,
    totals,
    debitNoteTotals: dnTotals,
    itc: { available: r2(totals.gst - dnTotals.gst) },
    warnings: withoutGstin.length
      ? [`${withoutGstin.length} purchase bill(s) have a supplier without a GSTIN — input credit cannot be claimed on these.`]
      : []
  };
}

/** GSTR-3B — the monthly summary and net tax payable. */
function gstr3b(params = {}) {
  const out = gstr1(params);
  const inward = gstr2(params);
  const payable = {
    cgst: r2(out.net.cgst - r2(inward.itc.available / 2)),
    sgst: r2(out.net.sgst - r2(inward.itc.available / 2)),
    igst: r2(out.net.igst)
  };
  return {
    period: out.period,
    store: out.store,
    outward: out.net,
    outwardByRate: out.b2c.concat(out.b2b.map((b) => ({ rate: b.rates.join(','), ...b }))),
    inward: { taxable: inward.totals.taxable, gst: inward.totals.gst, itc: inward.itc.available },
    payable: { ...payable, total: r2(Math.max(0, payable.cgst) + Math.max(0, payable.sgst) + Math.max(0, payable.igst)) },
    warnings: inward.warnings
  };
}

/**
 * Reconciliation — recomputes tax from the saved line items and compares it
 * with the document totals, so data-entry slips surface before filing.
 */
function reconcile(params = {}) {
  const { from, to } = range(params);
  const conn = db.get();
  const sales = conn.prepare(`SELECT s.id, s.no, s.date, s.subtotal, s.gst_amount, s.total,
      ROUND(COALESCE(SUM(si.taxable),0),2) AS line_taxable,
      ROUND(COALESCE(SUM(si.cgst + si.sgst + si.igst),0),2) AS line_gst
    FROM sales s LEFT JOIN sale_items si ON si.sale_id = s.id
    WHERE s.date >= ? AND s.date <= ? GROUP BY s.id`).all(from, to);
  const purchases = conn.prepare(`SELECT p.id, p.no, p.ref_no, p.date, p.subtotal, p.gst_amount,
      ROUND(COALESCE(SUM(pi.taxable),0),2) AS line_taxable,
      ROUND(COALESCE(SUM(pi.gst_amount),0),2) AS line_gst
    FROM purchases p LEFT JOIN purchase_items pi ON pi.purchase_id = p.id
    WHERE p.date >= ? AND p.date <= ? GROUP BY p.id`).all(from, to);

  const flag = (rows, label) => rows
    .filter((r) => Math.abs(r.subtotal - r.line_taxable) > 0.05 || Math.abs(r.gst_amount - r.line_gst) > 0.05)
    .map((r) => ({
      type: label,
      no: r.no,
      date: r.date,
      taxable_diff: r2(r.subtotal - r.line_taxable),
      gst_diff: r2(r.gst_amount - r.line_gst)
    }));

  const missingGstin = conn.prepare(`SELECT COUNT(*) AS n FROM purchases p
    LEFT JOIN suppliers s ON s.id = p.supplier_id
    WHERE p.date >= ? AND p.date <= ? AND (s.gstin IS NULL OR s.gstin = '')`).get(from, to).n;
  const b2bWithoutGstin = conn.prepare(`SELECT COUNT(*) AS n FROM sales s
    JOIN customers c ON c.id = s.customer_id
    WHERE s.date >= ? AND s.date <= ? AND s.total > 250000 AND (c.gstin IS NULL OR c.gstin = '')`).get(from, to).n;

  const mismatches = [...flag(sales, 'Sale'), ...flag(purchases, 'Purchase')];
  return {
    period: { from, to },
    checked: { sales: sales.length, purchases: purchases.length },
    mismatches,
    notes: [
      missingGstin ? `${missingGstin} purchase bill(s) in this period have no supplier GSTIN.` : null,
      b2bWithoutGstin ? `${b2bWithoutGstin} high-value bill(s) have a customer without a GSTIN.` : null,
      mismatches.length === 0 ? 'All documents in this period reconcile with their line items.' : null
    ].filter(Boolean),
    clean: mismatches.length === 0
  };
}

function financialYearRange(dateIso = today()) {
  return financialYear(dateIso);
}

module.exports = { gstr1, gstr2, gstr3b, reconcile, range, financialYearRange };

});

  define(["core/services/importer"], function (module, exports, require) {
'use strict';

const db = require('../db');
const products = require('./products');
const settings = require('./settings');
const { readAny, serialToIso, bytesFromBase64, bytesFromText } = require('../util/xlsx');
const { assert } = require('../util/errors');
const { r2, r3 } = require('../util/money');
const { isExpiryMonth } = require('../util/dates');

/**
 * Purchase-bill import. Distributor sheets never share a layout, so columns
 * are detected from the header row by keyword, and anything ambiguous comes
 * back to the screen as an editable preview instead of being guessed at.
 */
const FIELDS = {
  name: ['product', 'item', 'medicine', 'description', 'particulars', 'name', 'product name', 'item name'],
  pack: ['pack', 'packing'],
  batch: ['batch', 'batch no', 'batchno', 'b.no', 'bno', 'lot'],
  expiry: ['expiry', 'exp', 'exp date', 'expdt', 'exp.dt', 'expiry date'],
  qty: ['qty', 'quantity', 'qnty', 'nos', 'units', 'pcs'],
  free: ['free', 'free qty', 'scheme', 'bonus'],
  mrp: ['mrp', 'm.r.p', 'mrp rs', 'retail'],
  rate: ['rate', 'ptr', 'purchase rate', 'price', 'net rate', 'basic', 'trade rate'],
  disc: ['disc', 'discount', 'disc %', 'dis%', 'cd'],
  gst: ['gst', 'gst %', 'tax', 'igst', 'cgst+sgst', 'gst rate', 'vat'],
  hsn: ['hsn', 'hsn code'],
  mfr: ['mfr', 'manufacturer', 'company', 'mfg', 'marketer']
};

function normaliseHeader(cell) {
  return String(cell || '').toLowerCase().replace(/[._]/g, ' ').replace(/\s+/g, ' ').trim();
}

function detectColumns(headerRow) {
  const map = {};
  headerRow.forEach((cell, index) => {
    const h = normaliseHeader(cell);
    if (!h) return;
    for (const [field, keys] of Object.entries(FIELDS)) {
      if (map[field] !== undefined) continue;
      if (keys.some((k) => h === k)) { map[field] = index; return; }
    }
    for (const [field, keys] of Object.entries(FIELDS)) {
      if (map[field] !== undefined) continue;
      if (keys.some((k) => h.includes(k))) { map[field] = index; return; }
    }
  });
  return map;
}

/** Picks the header row — the first row that names a product and a quantity. */
function findHeaderRow(rows) {
  for (let i = 0; i < Math.min(rows.length, 25); i += 1) {
    const map = detectColumns(rows[i]);
    if (map.name !== undefined && (map.qty !== undefined || map.rate !== undefined)) return { index: i, map };
  }
  return { index: -1, map: {} };
}

function toNumber(value) {
  if (value === undefined || value === null || value === '') return 0;
  const cleaned = String(value).replace(/[₹,\s]/g, '').replace(/[^0-9.+-]/g, '');
  const n = Number(cleaned);
  return Number.isFinite(n) ? n : 0;
}

function parseExpiry(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return null;
  if (isExpiryMonth(raw)) return raw;
  if (/^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw.slice(0, 7);
  const serial = Number(raw);
  if (Number.isFinite(serial) && serial > 1000) {
    const iso = serialToIso(serial);
    if (iso) return iso.slice(0, 7);
  }
  const mmYY = raw.match(/^(\d{1,2})\s*[/\-.]\s*(\d{2}|\d{4})$/);
  if (mmYY) {
    const mm = String(Math.min(12, Math.max(1, Number(mmYY[1])))).padStart(2, '0');
    const yy = mmYY[2].length === 2 ? `20${mmYY[2]}` : mmYY[2];
    return `${yy}-${mm}`;
  }
  const monthName = raw.match(/^([A-Za-z]{3,9})[\s-]*(\d{2}|\d{4})$/);
  if (monthName) {
    const months = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
    const idx = months.indexOf(monthName[1].slice(0, 3).toLowerCase());
    if (idx >= 0) {
      const yy = monthName[2].length === 2 ? `20${monthName[2]}` : monthName[2];
      return `${yy}-${String(idx + 1).padStart(2, '0')}`;
    }
  }
  const dmy = raw.match(/^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2,4})$/);
  if (dmy) {
    const mm = String(Math.min(12, Math.max(1, Number(dmy[2])))).padStart(2, '0');
    const yy = dmy[3].length === 2 ? `20${dmy[3]}` : dmy[3];
    return `${yy}-${mm}`;
  }
  return null;
}

/** Units per pack from strings like "10x10", "1x15 TAB", "30 ML". */
function parsePack(value) {
  const raw = String(value ?? '').toLowerCase();
  const cross = raw.match(/(\d+)\s*[x*]\s*(\d+)/);
  if (cross) return Math.max(1, Number(cross[2]));
  const plain = raw.match(/(\d+)/);
  return plain ? Math.max(1, Number(plain[1])) : 1;
}

function matchProduct(name) {
  const conn = db.get();
  const clean = String(name || '').trim();
  if (!clean) return null;
  const exact = conn.prepare('SELECT * FROM products WHERE lower(name) = lower(?) AND active = 1').get(clean);
  if (exact) return exact;
  const like = conn.prepare('SELECT * FROM products WHERE name LIKE ? AND active = 1 ORDER BY length(name) LIMIT 1')
    .get(`${clean.split(/\s+/)[0]}%`);
  if (like && like.name.toLowerCase().startsWith(clean.slice(0, 4).toLowerCase())) return like;
  return null;
}

/**
 * Parses a spreadsheet into draft purchase lines. Nothing is written to the
 * database here — the operator reviews the preview and then saves.
 */
async function preview({ filename = '', base64 = '', text = '' }) {
  const buffer = base64 ? bytesFromBase64(base64) : bytesFromText(text);
  assert(buffer.length > 0, 'That file is empty.');
  assert(buffer.length < 12 * 1024 * 1024, 'That file is larger than 12 MB — please split it.');
  const rows = await readAny(buffer, filename);
  assert(rows.length > 1, 'No rows could be read from that file.');
  const { index, map } = findHeaderRow(rows);
  assert(index >= 0, 'Could not find a header row. The sheet needs column titles such as Product, Batch, Expiry, Qty, Rate, MRP.');

  const defaultGst = settings.num('default_gst_rate', 12);
  const body = rows.slice(index + 1);
  const lines = [];
  for (const row of body) {
    const cell = (field) => (map[field] === undefined ? '' : row[map[field]] ?? '');
    const name = String(cell('name')).trim();
    if (!name) continue;
    if (/^(total|grand total|sub total|net amount|amount)/i.test(name)) continue;
    const qty = Math.round(toNumber(cell('qty')));
    const rate = toNumber(cell('rate'));
    if (qty <= 0 && rate <= 0) continue;
    const packSize = map.pack !== undefined ? parsePack(cell('pack')) : 1;
    const matched = matchProduct(name);
    const expiry = parseExpiry(cell('expiry'));
    const gstRaw = toNumber(cell('gst'));
    const mrp = toNumber(cell('mrp'));
    const issues = [];
    if (!matched) issues.push('New medicine — will be created on import');
    if (!expiry) issues.push('Expiry missing or unreadable');
    if (qty <= 0) issues.push('Quantity missing');
    if (rate <= 0) issues.push('Rate missing');
    lines.push({
      source_name: name,
      product_id: matched?.id ?? null,
      product_name: matched?.name ?? name,
      manufacturer: String(cell('mfr')).trim(),
      hsn: String(cell('hsn')).trim() || '3004',
      pack_size: matched?.pack_size ?? packSize,
      batch_no: String(cell('batch')).trim().toUpperCase() || 'NA',
      expiry,
      qty_units: qty > 0 ? qty * (matched ? 1 : 1) : 0,
      free_units: Math.max(0, Math.round(toNumber(cell('free')))),
      mrp: r2(mrp),
      rate_per_unit: r3(rate),
      disc_pct: Math.min(100, Math.max(0, toNumber(cell('disc')))),
      gst_rate: [0, 5, 12, 18, 28].includes(gstRaw) ? gstRaw : (matched?.gst_rate ?? defaultGst),
      issues
    });
  }
  assert(lines.length > 0, 'No usable item rows were found in that file.');
  return {
    filename,
    headerRow: index + 1,
    columns: map,
    detected: Object.keys(map),
    lines,
    summary: {
      rows: lines.length,
      newProducts: lines.filter((l) => !l.product_id).length,
      withIssues: lines.filter((l) => l.issues.length > 0).length,
      value: r2(lines.reduce((s, l) => s + l.qty_units * l.rate_per_unit, 0))
    }
  };
}

/** Creates any medicines the sheet introduced, returning lines ready to save. */
function materialise(actor, { lines = [] }) {
  assert(Array.isArray(lines) && lines.length, 'Nothing to import.');
  return db.tx(() => lines.map((line) => {
    let productId = line.product_id ? Number(line.product_id) : null;
    if (!productId) {
      const created = products.save(actor, {
        name: line.product_name || line.source_name,
        manufacturer: line.manufacturer || '',
        hsn: line.hsn || '3004',
        gst_rate: line.gst_rate,
        pack_size: line.pack_size || 1,
        category: 'Medicine'
      });
      productId = created.id;
    }
    return {
      product_id: productId,
      batch_no: line.batch_no,
      expiry: line.expiry,
      mrp: line.mrp,
      qty_units: line.qty_units,
      free_units: line.free_units,
      rate_per_unit: line.rate_per_unit,
      disc_pct: line.disc_pct,
      gst_rate: line.gst_rate
    };
  }));
}

/** Medicine-master import — used to load an opening catalogue quickly. */
async function importProducts(actor, { filename = '', base64 = '', text = '' }) {
  const buffer = base64 ? bytesFromBase64(base64) : bytesFromText(text);
  const rows = await readAny(buffer, filename);
  const { index, map } = findHeaderRow(rows);
  assert(index >= 0, 'Could not find a header row with a product name column.');
  const created = [];
  const skipped = [];
  db.tx(() => {
    for (const row of rows.slice(index + 1)) {
      const cell = (f) => (map[f] === undefined ? '' : row[map[f]] ?? '');
      const name = String(cell('name')).trim();
      if (!name) continue;
      try {
        created.push(products.save(actor, {
          name,
          manufacturer: String(cell('mfr')).trim(),
          hsn: String(cell('hsn')).trim() || '3004',
          gst_rate: [0, 5, 12, 18, 28].includes(toNumber(cell('gst'))) ? toNumber(cell('gst')) : settings.num('default_gst_rate', 12),
          pack_size: map.pack !== undefined ? parsePack(cell('pack')) : 1
        }).name);
      } catch (err) {
        skipped.push({ name, reason: err.message });
      }
    }
  });
  return { created: created.length, skipped, names: created.slice(0, 50) };
}

module.exports = { preview, materialise, importProducts, detectColumns, parseExpiry, parsePack, toNumber };

});

  define(["core/services/ledger"], function (module, exports, require) {
'use strict';

const db = require('../db');
const { r2 } = require('../util/money');
const { nowStamp } = require('../util/dates');

const ACCOUNTS = ['cash', 'bank'];
const MODES = ['Cash', 'UPI', 'Card', 'Cheque', 'Bank Transfer', 'Credit'];

/** Maps a payment mode to the account it moves money in or out of. */
function accountForMode(mode) {
  return mode === 'Cash' ? 'cash' : 'bank';
}

/** Appends a cash/bank movement. Must be called inside a transaction. */
function post({ date, account, direction, amount, sourceType, sourceId, description }) {
  const value = r2(amount);
  if (value === 0) return null;
  const info = db.get().prepare(`INSERT INTO ledger
      (date, account, direction, amount, source_type, source_id, description, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)`)
    .run(date, account, direction, Math.abs(value), sourceType, sourceId ?? null, description ?? '', nowStamp());
  return Number(info.lastInsertRowid);
}

/** Removes entries created by a document that is being deleted/reversed. */
function reverseSource(sourceType, sourceId) {
  db.get().prepare('DELETE FROM ledger WHERE source_type = ? AND source_id = ?').run(sourceType, Number(sourceId));
}

function balances({ upto = null } = {}) {
  const clause = upto ? 'WHERE date <= ?' : '';
  const args = upto ? [upto] : [];
  const rows = db.get().prepare(`SELECT account,
      COALESCE(SUM(CASE WHEN direction = 'in' THEN amount ELSE 0 END), 0) AS credit,
      COALESCE(SUM(CASE WHEN direction = 'out' THEN amount ELSE 0 END), 0) AS debit
    FROM ledger ${clause} GROUP BY account`).all(...args);
  const out = { cash: 0, bank: 0, total: 0 };
  for (const r of rows) {
    if (out[r.account] === undefined) out[r.account] = 0;
    out[r.account] = r2(r.credit - r.debit);
  }
  out.total = r2(out.cash + out.bank);
  return out;
}

function entries({ from, to, account = '', limit = 500 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('date >= ?'); args.push(from); }
  if (to) { where.push('date <= ?'); args.push(to); }
  if (account) { where.push('account = ?'); args.push(account); }
  const rows = db.get().prepare(`SELECT * FROM ledger ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY date DESC, id DESC LIMIT ?`).all(...args, Math.min(Number(limit) || 500, 5000));
  const opening = from
    ? balances({ upto: from })
    : { cash: 0, bank: 0, total: 0 };
  const openingBefore = from
    ? (() => {
      const r = db.get().prepare(`SELECT
          COALESCE(SUM(CASE WHEN direction='in' THEN amount ELSE 0 END),0) AS credit,
          COALESCE(SUM(CASE WHEN direction='out' THEN amount ELSE 0 END),0) AS debit
        FROM ledger WHERE date < ? ${account ? 'AND account = ?' : ''}`)
        .get(...(account ? [from, account] : [from]));
      return r2(r.credit - r.debit);
    })()
    : 0;
  const totals = rows.reduce((acc, r) => {
    if (r.direction === 'in') acc.inflow = r2(acc.inflow + r.amount);
    else acc.outflow = r2(acc.outflow + r.amount);
    return acc;
  }, { inflow: 0, outflow: 0 });
  return { rows, opening: openingBefore, totals, closing: r2(openingBefore + totals.inflow - totals.outflow), snapshot: opening };
}

module.exports = { ACCOUNTS, MODES, accountForMode, post, reverseSource, balances, entries };

});

  define(["core/services/parties"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const v = require('../util/validate');
const { assert } = require('../util/errors');
const { r2 } = require('../util/money');
const { nowStamp } = require('../util/dates');

/**
 * Customers, doctors and suppliers share a shape, so one module handles all
 * three. Balances are derived from documents + payments, never stored.
 */

const CUSTOMER_BALANCE = `
  c.opening_balance
  + COALESCE((SELECT SUM(s.total) FROM sales s WHERE s.customer_id = c.id), 0)
  - COALESCE((SELECT SUM(r.total) FROM sale_returns r WHERE r.customer_id = c.id), 0)
  - COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.party_type = 'customer' AND p.party_id = c.id AND p.direction = 'in'), 0)
  + COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.party_type = 'customer' AND p.party_id = c.id AND p.direction = 'out'), 0)`;

const SUPPLIER_BALANCE = `
  s.opening_balance
  + COALESCE((SELECT SUM(p.total) FROM purchases p WHERE p.supplier_id = s.id), 0)
  - COALESCE((SELECT SUM(r.total) FROM purchase_returns r WHERE r.supplier_id = s.id), 0)
  - COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.party_type = 'supplier' AND p.party_id = s.id AND p.direction = 'out'), 0)
  + COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.party_type = 'supplier' AND p.party_id = s.id AND p.direction = 'in'), 0)`;

function listCustomers({ search = '', limit = 500, onlyActive = true } = {}) {
  const where = [];
  const args = [];
  if (onlyActive) where.push('c.active = 1');
  if (search) {
    where.push('(c.name LIKE ? OR c.phone LIKE ?)');
    args.push(`%${search}%`, `%${search}%`);
  }
  return db.get().prepare(`SELECT c.*, ROUND(${CUSTOMER_BALANCE}, 2) AS balance,
      (SELECT COUNT(*) FROM sales s WHERE s.customer_id = c.id) AS bill_count,
      (SELECT MAX(s.date) FROM sales s WHERE s.customer_id = c.id) AS last_visit
    FROM customers c ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY c.name LIMIT ?`).all(...args, Math.min(Number(limit) || 500, 5000));
}

function customerById(id) {
  return db.get().prepare(`SELECT c.*, ROUND(${CUSTOMER_BALANCE}, 2) AS balance FROM customers c WHERE c.id = ?`)
    .get(Number(id));
}

function saveCustomer(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist', 'cashier']);
  const id = payload.id ? v.integer(payload.id, 'Customer', { min: 1 }) : null;
  const data = {
    name: v.str(payload.name, 'Patient / customer name', { required: true, max: 120 }),
    phone: v.phone(payload.phone, 'Phone'),
    email: v.str(payload.email, 'Email', { max: 120 }),
    address: v.str(payload.address, 'Address', { max: 300 }),
    gstin: payload.gstin ? v.gstin(payload.gstin) : '',
    dob: v.date(payload.dob, 'Date of birth', { required: false }),
    notes: v.str(payload.notes, 'Notes', { max: 500 }),
    opening_balance: r2(v.number(payload.opening_balance, 'Opening balance', { min: -1e9, max: 1e9 })),
    active: v.bool(payload.active ?? 1)
  };
  if (id) {
    db.get().prepare(`UPDATE customers SET name=@name, phone=@phone, email=@email, address=@address,
      gstin=@gstin, dob=@dob, notes=@notes, opening_balance=@opening_balance, active=@active WHERE id=@id`)
      .run({ ...data, id });
    audit.log(actor, 'customer.update', 'customer', id, data.name);
    return customerById(id);
  }
  const info = db.get().prepare(`INSERT INTO customers
    (name, phone, email, address, gstin, dob, notes, opening_balance, active, created_at)
    VALUES (@name, @phone, @email, @address, @gstin, @dob, @notes, @opening_balance, @active, @created_at)`)
    .run({ ...data, created_at: nowStamp() });
  audit.log(actor, 'customer.create', 'customer', info.lastInsertRowid, data.name);
  return customerById(info.lastInsertRowid);
}

function customerHistory({ id, limit = 100 }) {
  const cid = v.integer(id, 'Customer', { required: true, min: 1 });
  const sales = db.get().prepare(`SELECT s.*, d.name AS doctor_name FROM sales s
    LEFT JOIN doctors d ON d.id = s.doctor_id
    WHERE s.customer_id = ? ORDER BY s.date DESC, s.id DESC LIMIT ?`).all(cid, Number(limit) || 100);
  const payments = db.get().prepare(`SELECT * FROM payments WHERE party_type = 'customer' AND party_id = ?
    ORDER BY date DESC, id DESC LIMIT ?`).all(cid, Number(limit) || 100);
  const items = db.get().prepare(`SELECT si.name, SUM(si.qty_units) AS units, MAX(s.date) AS last_date
    FROM sale_items si JOIN sales s ON s.id = si.sale_id
    WHERE s.customer_id = ? GROUP BY si.name ORDER BY units DESC LIMIT 20`).all(cid);
  return { customer: customerById(cid), sales, payments, items };
}

// ---------------------------------------------------------------- doctors

function listDoctors({ search = '', onlyActive = true } = {}) {
  const where = [];
  const args = [];
  if (onlyActive) where.push('d.active = 1');
  if (search) { where.push('d.name LIKE ?'); args.push(`%${search}%`); }
  return db.get().prepare(`SELECT d.*,
      (SELECT COUNT(*) FROM sales s WHERE s.doctor_id = d.id) AS referrals,
      COALESCE((SELECT SUM(c.amount) FROM doctor_commissions c WHERE c.doctor_id = d.id), 0) AS commission_total,
      COALESCE((SELECT SUM(c.amount) FROM doctor_commissions c WHERE c.doctor_id = d.id AND c.paid = 0), 0) AS commission_due
    FROM doctors d ${where.length ? `WHERE ${where.join(' AND ')}` : ''} ORDER BY d.name`).all(...args);
}

function saveDoctor(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const id = payload.id ? v.integer(payload.id, 'Doctor', { min: 1 }) : null;
  const data = {
    name: v.str(payload.name, 'Doctor name', { required: true, max: 120 }),
    phone: v.phone(payload.phone, 'Phone'),
    clinic: v.str(payload.clinic, 'Clinic / hospital', { max: 160 }),
    reg_no: v.str(payload.reg_no, 'Registration number', { max: 40 }),
    commission_pct: v.number(payload.commission_pct, 'Commission %', { min: 0, max: 100 }),
    active: v.bool(payload.active ?? 1)
  };
  if (id) {
    db.get().prepare(`UPDATE doctors SET name=@name, phone=@phone, clinic=@clinic, reg_no=@reg_no,
      commission_pct=@commission_pct, active=@active WHERE id=@id`).run({ ...data, id });
    audit.log(actor, 'doctor.update', 'doctor', id, data.name);
  } else {
    const info = db.get().prepare(`INSERT INTO doctors (name, phone, clinic, reg_no, commission_pct, active, created_at)
      VALUES (@name, @phone, @clinic, @reg_no, @commission_pct, @active, @created_at)`)
      .run({ ...data, created_at: nowStamp() });
    audit.log(actor, 'doctor.create', 'doctor', info.lastInsertRowid, data.name);
  }
  return listDoctors({});
}

function doctorCommissions({ doctorId = null, from = null, to = null, unpaidOnly = false } = {}) {
  const where = [];
  const args = [];
  if (doctorId) { where.push('c.doctor_id = ?'); args.push(Number(doctorId)); }
  if (from) { where.push('c.date >= ?'); args.push(from); }
  if (to) { where.push('c.date <= ?'); args.push(to); }
  if (unpaidOnly) where.push('c.paid = 0');
  return db.get().prepare(`SELECT c.*, d.name AS doctor_name, s.no AS invoice_no
    FROM doctor_commissions c JOIN doctors d ON d.id = c.doctor_id
    LEFT JOIN sales s ON s.id = c.sale_id
    ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY c.date DESC, c.id DESC LIMIT 1000`).all(...args);
}

function settleCommission(actor, { ids = [], paid = 1 }) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  assert(Array.isArray(ids) && ids.length, 'Select at least one commission entry.');
  return db.tx(() => {
    const stmt = db.get().prepare('UPDATE doctor_commissions SET paid = ? WHERE id = ?');
    for (const id of ids) stmt.run(paid ? 1 : 0, Number(id));
    audit.log(actor, 'doctor.commission.settle', 'doctor_commission', ids.join(','), { paid });
    return { ok: true, updated: ids.length };
  });
}

// --------------------------------------------------------------- suppliers

function listSuppliers({ search = '', onlyActive = true } = {}) {
  const where = [];
  const args = [];
  if (onlyActive) where.push('s.active = 1');
  if (search) { where.push('(s.name LIKE ? OR s.phone LIKE ?)'); args.push(`%${search}%`, `%${search}%`); }
  return db.get().prepare(`SELECT s.*, ROUND(${SUPPLIER_BALANCE}, 2) AS balance,
      (SELECT COUNT(*) FROM purchases p WHERE p.supplier_id = s.id) AS bill_count,
      (SELECT MAX(p.date) FROM purchases p WHERE p.supplier_id = s.id) AS last_purchase
    FROM suppliers s ${where.length ? `WHERE ${where.join(' AND ')}` : ''} ORDER BY s.name LIMIT ?`)
    .all(...args, 2000);
}

function supplierById(id) {
  return db.get().prepare(`SELECT s.*, ROUND(${SUPPLIER_BALANCE}, 2) AS balance FROM suppliers s WHERE s.id = ?`)
    .get(Number(id));
}

function saveSupplier(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const id = payload.id ? v.integer(payload.id, 'Supplier', { min: 1 }) : null;
  const data = {
    name: v.str(payload.name, 'Supplier name', { required: true, max: 120 }),
    phone: v.phone(payload.phone, 'Phone'),
    email: v.str(payload.email, 'Email', { max: 120 }),
    address: v.str(payload.address, 'Address', { max: 300 }),
    gstin: payload.gstin ? v.gstin(payload.gstin) : '',
    dl_no: v.str(payload.dl_no, 'Drug licence number', { max: 60 }),
    opening_balance: r2(v.number(payload.opening_balance, 'Opening balance', { min: -1e9, max: 1e9 })),
    active: v.bool(payload.active ?? 1)
  };
  if (id) {
    db.get().prepare(`UPDATE suppliers SET name=@name, phone=@phone, email=@email, address=@address,
      gstin=@gstin, dl_no=@dl_no, opening_balance=@opening_balance, active=@active WHERE id=@id`)
      .run({ ...data, id });
    audit.log(actor, 'supplier.update', 'supplier', id, data.name);
    return supplierById(id);
  }
  const info = db.get().prepare(`INSERT INTO suppliers
    (name, phone, email, address, gstin, dl_no, opening_balance, active, created_at)
    VALUES (@name, @phone, @email, @address, @gstin, @dl_no, @opening_balance, @active, @created_at)`)
    .run({ ...data, created_at: nowStamp() });
  audit.log(actor, 'supplier.create', 'supplier', info.lastInsertRowid, data.name);
  return supplierById(info.lastInsertRowid);
}

function supplierHistory({ id, limit = 100 }) {
  const sid = v.integer(id, 'Supplier', { required: true, min: 1 });
  return {
    supplier: supplierById(sid),
    purchases: db.get().prepare(`SELECT * FROM purchases WHERE supplier_id = ?
      ORDER BY date DESC, id DESC LIMIT ?`).all(sid, Number(limit) || 100),
    payments: db.get().prepare(`SELECT * FROM payments WHERE party_type = 'supplier' AND party_id = ?
      ORDER BY date DESC, id DESC LIMIT ?`).all(sid, Number(limit) || 100)
  };
}

function deactivate(actor, { type, id }) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const table = { customer: 'customers', doctor: 'doctors', supplier: 'suppliers' }[type];
  assert(table, 'Unknown record type.');
  const rid = v.integer(id, 'Record', { required: true, min: 1 });
  db.get().prepare(`UPDATE ${table} SET active = 0 WHERE id = ?`).run(rid);
  audit.log(actor, `${type}.deactivate`, type, rid);
  return { ok: true };
}

module.exports = {
  listCustomers, customerById, saveCustomer, customerHistory,
  listDoctors, saveDoctor, doctorCommissions, settleCommission,
  listSuppliers, supplierById, saveSupplier, supplierHistory, deactivate,
  CUSTOMER_BALANCE, SUPPLIER_BALANCE
};

});

  define(["core/services/payments"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const ledger = require('./ledger');
const parties = require('./parties');
const v = require('../util/validate');
const { assert } = require('../util/errors');
const { r2 } = require('../util/money');
const { nowStamp, today } = require('../util/dates');

const CATEGORIES = ['Rent', 'Salary', 'Electricity', 'Transport', 'Packing', 'Telephone', 'Maintenance', 'Licence & Fees', 'Tea & Refreshment', 'General', 'Other'];

/** Records a receipt from a customer or a payment to a supplier. */
function record(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist', 'cashier']);
  const partyType = v.oneOf(payload.party_type, 'Party type', ['customer', 'supplier'], 'customer');
  const partyId = v.integer(payload.party_id, partyType === 'customer' ? 'Customer' : 'Supplier', { required: true, min: 1 });
  const direction = v.oneOf(payload.direction, 'Direction', ['in', 'out'], partyType === 'customer' ? 'in' : 'out');
  const amount = r2(v.number(payload.amount, 'Amount', { required: true, min: 0.01, max: 1e9 }));
  const mode = v.oneOf(payload.mode, 'Payment mode', ledger.MODES.filter((m) => m !== 'Credit'), 'Cash');
  const date = v.date(payload.date, 'Date', { required: false, fallback: 'today' }) || today();
  const refNo = v.str(payload.ref_no, 'Reference', { max: 60 });
  const notes = v.str(payload.notes, 'Notes', { max: 300 });
  const account = ledger.accountForMode(mode);

  const party = partyType === 'customer' ? parties.customerById(partyId) : parties.supplierById(partyId);
  assert(party, 'That party no longer exists.');

  return db.tx(() => {
    const info = db.get().prepare(`INSERT INTO payments
      (date, party_type, party_id, party_name, direction, amount, mode, account, ref_no, notes, created_at, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
      .run(date, partyType, partyId, party.name, direction, amount, mode, account, refNo, notes,
        nowStamp(), actor?.username ?? '');
    const id = Number(info.lastInsertRowid);
    ledger.post({
      date,
      account,
      direction,
      amount,
      sourceType: 'payment',
      sourceId: id,
      description: `${direction === 'in' ? 'Received from' : 'Paid to'} ${party.name}${refNo ? ` (${refNo})` : ''}`
    });
    audit.log(actor, 'payment.record', 'payment', id, { partyType, partyId, amount, mode });
    return { id, balance: (partyType === 'customer' ? parties.customerById(partyId) : parties.supplierById(partyId)).balance };
  });
}

function remove(actor, { id }) {
  auth.requireRole(actor, ['admin']);
  const pid = v.integer(id, 'Payment', { required: true, min: 1 });
  return db.tx(() => {
    const row = db.get().prepare('SELECT * FROM payments WHERE id = ?').get(pid);
    assert(row, 'That payment no longer exists.');
    assert(!row.sale_id && !row.purchase_id, 'This receipt was taken with a bill. Edit or delete the bill instead.');
    ledger.reverseSource('payment', pid);
    db.get().prepare('DELETE FROM payments WHERE id = ?').run(pid);
    audit.log(actor, 'payment.delete', 'payment', pid, row);
    return { ok: true };
  });
}

function list({ from, to, partyType = '', direction = '', limit = 500 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('date >= ?'); args.push(from); }
  if (to) { where.push('date <= ?'); args.push(to); }
  if (partyType) { where.push('party_type = ?'); args.push(partyType); }
  if (direction) { where.push('direction = ?'); args.push(direction); }
  const rows = db.get().prepare(`SELECT * FROM payments ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY date DESC, id DESC LIMIT ?`).all(...args, Math.min(Number(limit) || 500, 5000));
  const totals = rows.reduce((a, r) => {
    if (r.direction === 'in') a.received = r2(a.received + r.amount); else a.paid = r2(a.paid + r.amount);
    return a;
  }, { received: 0, paid: 0 });
  return { rows, totals };
}

// ---------------------------------------------------------------- expenses

function saveExpense(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const id = payload.id ? v.integer(payload.id, 'Expense', { min: 1 }) : null;
  const date = v.date(payload.date, 'Date', { required: false, fallback: 'today' }) || today();
  const category = v.str(payload.category, 'Category', { required: true, max: 60 });
  const payee = v.str(payload.payee, 'Paid to', { max: 120 });
  const amount = r2(v.number(payload.amount, 'Amount', { required: true, min: 0.01, max: 1e9 }));
  const account = v.oneOf(payload.account, 'Account', ledger.ACCOUNTS, 'cash');
  const notes = v.str(payload.notes, 'Notes', { max: 300 });

  return db.tx(() => {
    let expenseId = id;
    if (id) {
      const row = db.get().prepare('SELECT * FROM expenses WHERE id = ?').get(id);
      assert(row, 'That expense no longer exists.');
      db.get().prepare(`UPDATE expenses SET date=?, category=?, payee=?, amount=?, account=?, notes=? WHERE id=?`)
        .run(date, category, payee, amount, account, notes, id);
      ledger.reverseSource('expense', id);
    } else {
      const info = db.get().prepare(`INSERT INTO expenses (date, category, payee, amount, account, notes, created_at, created_by)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)`).run(date, category, payee, amount, account, notes, nowStamp(), actor?.username ?? '');
      expenseId = Number(info.lastInsertRowid);
    }
    ledger.post({
      date, account, direction: 'out', amount, sourceType: 'expense', sourceId: expenseId,
      description: `${category}${payee ? ` — ${payee}` : ''}`
    });
    audit.log(actor, id ? 'expense.update' : 'expense.create', 'expense', expenseId, { category, amount });
    return { id: expenseId };
  });
}

function listExpenses({ from, to, category = '', limit = 500 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('date >= ?'); args.push(from); }
  if (to) { where.push('date <= ?'); args.push(to); }
  if (category) { where.push('category = ?'); args.push(category); }
  const rows = db.get().prepare(`SELECT * FROM expenses ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY date DESC, id DESC LIMIT ?`).all(...args, Math.min(Number(limit) || 500, 5000));
  const byCategory = {};
  let total = 0;
  for (const r of rows) {
    byCategory[r.category] = r2((byCategory[r.category] || 0) + r.amount);
    total = r2(total + r.amount);
  }
  return { rows, total, byCategory };
}

function removeExpense(actor, { id }) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const eid = v.integer(id, 'Expense', { required: true, min: 1 });
  return db.tx(() => {
    const row = db.get().prepare('SELECT * FROM expenses WHERE id = ?').get(eid);
    assert(row, 'That expense no longer exists.');
    ledger.reverseSource('expense', eid);
    db.get().prepare('DELETE FROM expenses WHERE id = ?').run(eid);
    audit.log(actor, 'expense.delete', 'expense', eid, row);
    return { ok: true };
  });
}

/** Manual cash <-> bank movement (deposit / withdrawal). */
function transfer(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const amount = r2(v.number(payload.amount, 'Amount', { required: true, min: 0.01, max: 1e9 }));
  const from = v.oneOf(payload.from, 'From account', ledger.ACCOUNTS, 'cash');
  const to = v.oneOf(payload.to, 'To account', ledger.ACCOUNTS, 'bank');
  assert(from !== to, 'Choose two different accounts.');
  const date = v.date(payload.date, 'Date', { required: false, fallback: 'today' }) || today();
  const notes = v.str(payload.notes, 'Notes', { max: 200 });
  return db.tx(() => {
    const label = `${from === 'cash' ? 'Cash to bank' : 'Bank to cash'}${notes ? ` — ${notes}` : ''}`;
    const outId = ledger.post({ date, account: from, direction: 'out', amount, sourceType: 'transfer', sourceId: null, description: label });
    ledger.post({ date, account: to, direction: 'in', amount, sourceType: 'transfer', sourceId: outId, description: label });
    audit.log(actor, 'account.transfer', 'ledger', outId, { from, to, amount });
    return { ok: true, balances: ledger.balances() };
  });
}

module.exports = { CATEGORIES, record, remove, list, saveExpense, listExpenses, removeExpense, transfer };

});

  define(["core/services/products"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const settings = require('./settings');
const v = require('../util/validate');
const { assert } = require('../util/errors');
const { r2, r3, int } = require('../util/money');
const { nowStamp, today, addDays, expiryEndDate } = require('../util/dates');

const CATEGORIES = ['Medicine', 'Tablet', 'Syrup', 'Injection', 'Ointment', 'Drops', 'Surgical', 'Cosmetic', 'General', 'Other'];
const SCHEDULES = ['General', 'Schedule H', 'Schedule H1', 'Schedule X', 'OTC', 'Narcotic'];

const STOCK_SELECT = `
  SELECT p.*,
         COALESCE(s.qty_units, 0)  AS stock_units,
         COALESCE(s.batch_count, 0) AS batch_count,
         s.min_expiry,
         s.mrp AS last_mrp,
         s.rate AS last_rate
  FROM products p
  LEFT JOIN (
    SELECT b.product_id,
           SUM(b.qty_units) AS qty_units,
           COUNT(*)         AS batch_count,
           MIN(b.expiry)    AS min_expiry,
           MAX(b.mrp)       AS mrp,
           MAX(b.rate_per_unit) AS rate
    FROM batches b
    WHERE b.qty_units > 0
    GROUP BY b.product_id
  ) s ON s.product_id = p.id`;

function decorate(row) {
  if (!row) return row;
  const pack = Math.max(1, int(row.pack_size, 1));
  const units = int(row.stock_units, 0);
  return {
    ...row,
    active: !!row.active,
    allow_loose: !!row.allow_loose,
    pack_size: pack,
    stock_units: units,
    stock_packs: Math.floor(units / pack),
    stock_loose: units % pack,
    stock_label: pack > 1
      ? `${Math.floor(units / pack)} ${row.pack_label}${units % pack ? ` + ${units % pack} ${row.unit_label}` : ''}`
      : `${units} ${row.unit_label}`,
    low_stock: row.reorder_level > 0 && units <= row.reorder_level
  };
}

function list({ search = '', category = '', onlyActive = true, lowStock = false, limit = 500 } = {}) {
  const where = [];
  const args = [];
  if (onlyActive) where.push('p.active = 1');
  if (search) {
    where.push('(p.name LIKE ? OR p.generic LIKE ? OR p.manufacturer LIKE ?)');
    const q = `%${search}%`;
    args.push(q, q, q);
  }
  if (category) { where.push('p.category = ?'); args.push(category); }
  let sql = `${STOCK_SELECT} ${where.length ? `WHERE ${where.join(' AND ')}` : ''} ORDER BY p.name LIMIT ?`;
  let rows = db.get().prepare(sql).all(...args, Math.min(Number(limit) || 500, 5000)).map(decorate);
  if (lowStock) rows = rows.filter((r) => r.low_stock || r.stock_units === 0);
  return rows;
}

function byId(id) {
  return decorate(db.get().prepare(`${STOCK_SELECT} WHERE p.id = ?`).get(Number(id)));
}

/** Fast type-ahead used by the billing screen. Batches come along for the ride. */
function search({ q = '', limit = 12, inStockOnly = false } = {}) {
  const term = String(q).trim();
  if (!term) return [];
  const like = `${term}%`;
  const contains = `%${term}%`;
  const rows = db.get().prepare(`${STOCK_SELECT}
    WHERE p.active = 1 AND (p.name LIKE ? OR p.generic LIKE ? OR p.name LIKE ? OR p.generic LIKE ?)
    ORDER BY CASE WHEN p.name LIKE ? THEN 0 ELSE 1 END, p.name
    LIMIT ?`).all(like, like, contains, contains, like, Math.min(Number(limit) || 12, 50)).map(decorate);
  const filtered = inStockOnly ? rows.filter((r) => r.stock_units > 0) : rows;
  return filtered.map((r) => ({ ...r, batches: batchesFor(r.id, { onlyInStock: true }) }));
}

function save(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const id = payload.id ? v.integer(payload.id, 'Product', { min: 1 }) : null;
  const data = {
    name: v.str(payload.name, 'Medicine name', { required: true, max: 120 }),
    generic: v.str(payload.generic, 'Salt / generic name', { max: 160 }),
    manufacturer: v.str(payload.manufacturer, 'Manufacturer', { max: 120 }),
    category: v.oneOf(payload.category, 'Category', CATEGORIES, 'Medicine'),
    hsn: v.str(payload.hsn, 'HSN code', { max: 12 }),
    gst_rate: v.number(payload.gst_rate, 'GST %', { min: 0, max: 28, fallback: settings.num('default_gst_rate', 12) }),
    pack_size: v.integer(payload.pack_size, 'Units per pack', { min: 1, max: 10000, fallback: 1 }) || 1,
    pack_label: v.str(payload.pack_label, 'Pack label', { max: 20 }) || 'Strip',
    unit_label: v.str(payload.unit_label, 'Unit label', { max: 20 }) || 'Tablet',
    allow_loose: v.bool(payload.allow_loose ?? 1),
    rack: v.str(payload.rack, 'Rack', { max: 30 }),
    schedule_type: v.oneOf(payload.schedule_type, 'Drug schedule', SCHEDULES, 'General'),
    reorder_level: v.integer(payload.reorder_level, 'Reorder level', { min: 0, max: 1000000, fallback: 0 }),
    active: v.bool(payload.active ?? 1)
  };
  assert([0, 5, 12, 18, 28].includes(Number(data.gst_rate)), 'GST % must be 0, 5, 12, 18 or 28.');

  const dup = db.get().prepare('SELECT id FROM products WHERE lower(name) = lower(?) AND id <> ?')
    .get(data.name, id ?? 0);
  assert(!dup, `"${data.name}" already exists in the medicine master.`);

  if (id) {
    db.get().prepare(`UPDATE products SET name=@name, generic=@generic, manufacturer=@manufacturer,
      category=@category, hsn=@hsn, gst_rate=@gst_rate, pack_size=@pack_size, pack_label=@pack_label,
      unit_label=@unit_label, allow_loose=@allow_loose, rack=@rack, schedule_type=@schedule_type,
      reorder_level=@reorder_level, active=@active, updated_at=@updated_at WHERE id=@id`)
      .run({ ...data, id, updated_at: nowStamp() });
    audit.log(actor, 'product.update', 'product', id, data.name);
    return byId(id);
  }
  const info = db.get().prepare(`INSERT INTO products
    (name, generic, manufacturer, category, hsn, gst_rate, pack_size, pack_label, unit_label,
     allow_loose, rack, schedule_type, reorder_level, active, created_at, updated_at)
    VALUES (@name, @generic, @manufacturer, @category, @hsn, @gst_rate, @pack_size, @pack_label,
            @unit_label, @allow_loose, @rack, @schedule_type, @reorder_level, @active, @created_at, @created_at)`)
    .run({ ...data, created_at: nowStamp() });
  audit.log(actor, 'product.create', 'product', info.lastInsertRowid, data.name);
  return byId(info.lastInsertRowid);
}

function remove(actor, { id }) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const pid = v.integer(id, 'Product', { required: true, min: 1 });
  const stock = db.get().prepare('SELECT COALESCE(SUM(qty_units),0) AS n FROM batches WHERE product_id = ?').get(pid).n;
  const sold = db.get().prepare('SELECT COUNT(*) AS n FROM sale_items WHERE product_id = ?').get(pid).n;
  if (stock > 0 || sold > 0) {
    db.get().prepare('UPDATE products SET active = 0, updated_at = ? WHERE id = ?').run(nowStamp(), pid);
    audit.log(actor, 'product.deactivate', 'product', pid);
    return { ok: true, deactivated: true };
  }
  db.get().prepare('DELETE FROM products WHERE id = ?').run(pid);
  audit.log(actor, 'product.delete', 'product', pid);
  return { ok: true, deleted: true };
}

// ---------------------------------------------------------------- batches

function batchesFor(productId, { onlyInStock = false } = {}) {
  const rows = db.get().prepare(`SELECT b.*, p.pack_size, p.pack_label, p.unit_label
    FROM batches b JOIN products p ON p.id = b.product_id
    WHERE b.product_id = ? ${onlyInStock ? 'AND b.qty_units > 0' : ''}
    ORDER BY b.expiry, b.batch_no`).all(Number(productId));
  const ref = today();
  return rows.map((b) => {
    const pack = Math.max(1, int(b.pack_size, 1));
    const end = expiryEndDate(b.expiry);
    return {
      ...b,
      pack_size: pack,
      qty_packs: Math.floor(b.qty_units / pack),
      qty_loose: b.qty_units % pack,
      expired: end ? end < ref : false,
      expiring_soon: end ? end >= ref && end <= addDays(ref, settings.num('expiry_alert_days', 90)) : false
    };
  });
}

function saveBatch(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const productId = v.integer(payload.product_id, 'Medicine', { required: true, min: 1 });
  const product = db.get().prepare('SELECT * FROM products WHERE id = ?').get(productId);
  assert(product, 'Select a valid medicine first.');
  const batchNo = v.str(payload.batch_no, 'Batch number', { required: true, max: 40 }).toUpperCase();
  const expiry = v.expiry(payload.expiry, 'Expiry');
  const mrp = v.number(payload.mrp, 'MRP', { required: true, min: 0, max: 1000000 });
  const ratePerUnit = v.number(payload.rate_per_unit, 'Purchase rate per unit', { min: 0, max: 1000000 });
  const id = payload.id ? v.integer(payload.id, 'Batch', { min: 1 }) : null;
  const qtyUnits = v.integer(payload.qty_units, 'Quantity', { min: 0, max: 10000000, fallback: 0 });

  if (id) {
    const existing = db.get().prepare('SELECT * FROM batches WHERE id = ?').get(id);
    assert(existing, 'That batch no longer exists.');
    db.get().prepare(`UPDATE batches SET batch_no = ?, expiry = ?, mrp = ?, rate_per_unit = ? WHERE id = ?`)
      .run(batchNo, expiry, r2(mrp), r3(ratePerUnit), id);
    audit.log(actor, 'batch.update', 'batch', id, { product: product.name, batchNo });
    return batchesFor(productId).find((b) => b.id === id);
  }
  const info = db.get().prepare(`INSERT INTO batches (product_id, batch_no, expiry, mrp, rate_per_unit, qty_units, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(product_id, batch_no, expiry) DO UPDATE SET
      mrp = excluded.mrp, rate_per_unit = excluded.rate_per_unit, qty_units = batches.qty_units + excluded.qty_units`)
    .run(productId, batchNo, expiry, r2(mrp), r3(ratePerUnit), qtyUnits, nowStamp());
  audit.log(actor, 'batch.create', 'batch', info.lastInsertRowid, { product: product.name, batchNo, qtyUnits });
  return db.get().prepare('SELECT * FROM batches WHERE product_id = ? AND batch_no = ? AND expiry = ?')
    .get(productId, batchNo, expiry);
}

/**
 * Finds or creates the batch row for a purchase line. Used inside the
 * purchase transaction, so it never opens one of its own.
 */
function upsertBatch({ productId, batchNo, expiry, mrp, ratePerUnit }) {
  const conn = db.get();
  const existing = conn.prepare('SELECT * FROM batches WHERE product_id = ? AND batch_no = ? AND expiry = ?')
    .get(productId, batchNo, expiry);
  if (existing) {
    conn.prepare('UPDATE batches SET mrp = ?, rate_per_unit = ? WHERE id = ?')
      .run(r2(mrp), r3(ratePerUnit), existing.id);
    return existing.id;
  }
  const info = conn.prepare(`INSERT INTO batches (product_id, batch_no, expiry, mrp, rate_per_unit, qty_units, created_at)
    VALUES (?, ?, ?, ?, ?, 0, ?)`).run(productId, batchNo, expiry, r2(mrp), r3(ratePerUnit), nowStamp());
  return Number(info.lastInsertRowid);
}

/** Positive `delta` adds stock, negative removes it. Refuses to go below zero. */
function moveStock(batchId, delta, { allowNegative = false } = {}) {
  const conn = db.get();
  const batch = conn.prepare('SELECT b.*, p.name FROM batches b JOIN products p ON p.id = b.product_id WHERE b.id = ?').get(batchId);
  assert(batch, 'That batch no longer exists.');
  const next = int(batch.qty_units) + int(delta);
  assert(allowNegative || next >= 0,
    `Not enough stock for ${batch.name} (batch ${batch.batch_no}). Available: ${batch.qty_units}, needed: ${Math.abs(delta)}.`,
    'INSUFFICIENT_STOCK');
  conn.prepare('UPDATE batches SET qty_units = ? WHERE id = ?').run(next, batchId);
  return next;
}

function adjustStock(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const batchId = v.integer(payload.batch_id, 'Batch', { required: true, min: 1 });
  const qty = v.integer(payload.qty_units, 'Quantity', { required: true, min: -10000000, max: 10000000 });
  assert(qty !== 0, 'Enter a quantity to add or remove.');
  const reason = v.str(payload.reason, 'Reason', { required: true, max: 160 });
  return db.tx(() => {
    const batch = db.get().prepare('SELECT * FROM batches WHERE id = ?').get(batchId);
    assert(batch, 'That batch no longer exists.');
    moveStock(batchId, qty);
    db.get().prepare(`INSERT INTO stock_adjustments (date, batch_id, product_id, qty_units, reason, created_at, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?)`)
      .run(today(), batchId, batch.product_id, qty, reason, nowStamp(), actor?.username ?? '');
    audit.log(actor, 'stock.adjust', 'batch', batchId, { qty, reason });
    return { ok: true, stock: byId(batch.product_id) };
  });
}

function deleteBatch(actor, { id }) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const bid = v.integer(id, 'Batch', { required: true, min: 1 });
  const used = db.get().prepare(`SELECT
      (SELECT COUNT(*) FROM sale_items WHERE batch_id = ?) +
      (SELECT COUNT(*) FROM purchase_items WHERE batch_id = ?) AS n`).get(bid, bid).n;
  assert(used === 0, 'This batch appears on saved bills and cannot be deleted. Adjust its stock instead.');
  db.get().prepare('DELETE FROM batches WHERE id = ?').run(bid);
  audit.log(actor, 'batch.delete', 'batch', bid);
  return { ok: true };
}

/** First-expiry-first-out picking for the billing screen. */
function allocate(productId, unitsNeeded) {
  const batches = db.get().prepare(`SELECT * FROM batches WHERE product_id = ? AND qty_units > 0
    ORDER BY expiry, id`).all(Number(productId));
  const ref = today();
  const picks = [];
  let remaining = int(unitsNeeded);
  for (const b of batches) {
    if (remaining <= 0) break;
    const end = expiryEndDate(b.expiry);
    if (end && end < ref) continue; // never auto-pick expired stock
    const take = Math.min(remaining, b.qty_units);
    picks.push({ batch_id: b.id, batch_no: b.batch_no, expiry: b.expiry, mrp: b.mrp, rate_per_unit: b.rate_per_unit, qty_units: take });
    remaining -= take;
  }
  return { picks, shortfall: remaining };
}

function expiryReport({ withinDays = 90, includeExpired = true } = {}) {
  const limit = addDays(today(), Number(withinDays) || 90);
  const rows = db.get().prepare(`SELECT b.*, p.name, p.pack_size, p.pack_label, p.unit_label, p.manufacturer
    FROM batches b JOIN products p ON p.id = b.product_id
    WHERE b.qty_units > 0 ORDER BY b.expiry`).all();
  const ref = today();
  return rows
    .map((b) => {
      const end = expiryEndDate(b.expiry);
      return { ...b, end, value: r2(b.qty_units * b.rate_per_unit), expired: end < ref };
    })
    .filter((b) => (b.expired ? includeExpired : b.end <= limit));
}

function lowStockReport() {
  return list({ onlyActive: true, limit: 5000 })
    .filter((p) => p.stock_units === 0 || (p.reorder_level > 0 && p.stock_units <= p.reorder_level))
    .sort((a, b) => a.stock_units - b.stock_units);
}

module.exports = {
  CATEGORIES, SCHEDULES, list, byId, search, save, remove,
  batchesFor, saveBatch, upsertBatch, moveStock, adjustStock, deleteBatch,
  allocate, expiryReport, lowStockReport, decorate
};

});

  define(["core/services/purchases"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const settings = require('./settings');
const ledger = require('./ledger');
const parties = require('./parties');
const products = require('./products');
const v = require('../util/validate');
const { assert } = require('../util/errors');
const { r2, r3, lineTotals, roundOff } = require('../util/money');
const { nowStamp, today } = require('../util/dates');

function create(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const date = v.date(payload.date, 'Purchase date', { required: false, fallback: 'today' }) || today();
  const refNo = v.str(payload.ref_no, 'Supplier bill number', { max: 60 });
  const interState = v.bool(payload.inter_state);
  const notes = v.str(payload.notes, 'Notes', { max: 300 });
  const mode = v.oneOf(payload.payment_mode, 'Payment mode', ledger.MODES, 'Credit');
  assert(Array.isArray(payload.items) && payload.items.length > 0, 'Add at least one item to the purchase.');
  assert(payload.items.length <= 300, 'A single purchase can hold up to 300 lines.');

  return db.tx(() => {
    const conn = db.get();
    const supplierId = v.integer(payload.supplier_id, 'Supplier', { required: true, min: 1 });
    const supplier = parties.supplierById(supplierId);
    assert(supplier, 'Select a valid supplier.');

    if (refNo) {
      const dup = conn.prepare('SELECT no FROM purchases WHERE supplier_id = ? AND ref_no = ?').get(supplierId, refNo);
      assert(!dup, `Bill ${refNo} from ${supplier.name} is already entered as ${dup?.no}.`);
    }

    const lines = [];
    for (const [index, raw] of payload.items.entries()) {
      const at = `Line ${index + 1}`;
      const productId = v.integer(raw.product_id, `${at}: medicine`, { required: true, min: 1 });
      const product = conn.prepare('SELECT * FROM products WHERE id = ?').get(productId);
      assert(product, `${at}: that medicine no longer exists.`);
      const batchNo = v.str(raw.batch_no, `${at}: batch number`, { required: true, max: 40 }).toUpperCase();
      const expiry = v.expiry(raw.expiry, `${at}: expiry`);
      const mrp = v.number(raw.mrp, `${at}: MRP`, { required: true, min: 0, max: 1000000 });
      const qty = v.integer(raw.qty_units, `${at}: quantity`, { required: true, min: 1, max: 10000000 });
      const free = v.integer(raw.free_units, `${at}: free quantity`, { min: 0, max: 10000000, fallback: 0 });
      const rate = v.number(raw.rate_per_unit, `${at}: purchase rate`, { required: true, min: 0, max: 1000000 });
      const discPct = v.number(raw.disc_pct, `${at}: discount %`, { min: 0, max: 100 });
      const gstRate = v.number(raw.gst_rate ?? product.gst_rate, `${at}: GST %`, { min: 0, max: 28 });
      const t = lineTotals({ qty, rate, discPct, gstRate, interState });
      // Free goods dilute the landed cost per unit, which is what stock is valued at.
      const landed = r3(qty + free > 0 ? t.taxable / (qty + free) : 0);
      lines.push({
        product_id: productId,
        name: product.name,
        batch_no: batchNo,
        expiry,
        mrp: r2(mrp),
        qty_units: qty,
        free_units: free,
        rate_per_unit: r3(rate),
        disc_pct: discPct,
        gst_rate: gstRate,
        taxable: t.taxable,
        gst_amount: t.gstAmount,
        total: t.total,
        landed_cost: landed
      });
    }

    const subtotal = r2(lines.reduce((s, l) => s + l.taxable, 0));
    const gstAmount = r2(lines.reduce((s, l) => s + l.gst_amount, 0));
    const discount = r2(lines.reduce((s, l) => s + (l.qty_units * l.rate_per_unit * l.disc_pct / 100), 0));
    const gross = r2(subtotal + gstAmount);
    const rounded = roundOff(gross);
    const total = rounded.total;
    const paid = r2(v.number(payload.paid, 'Amount paid', { min: 0, max: 1e9, fallback: 0 }));
    assert(paid <= total + 0.01, 'Amount paid cannot be more than the bill total.');

    const no = settings.nextNumber('purchase', 'purchase_prefix');
    const info = conn.prepare(`INSERT INTO purchases
      (no, date, supplier_id, ref_no, inter_state, subtotal, discount, gst_amount, round_off, total, paid, notes, created_at, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
      .run(no, date, supplierId, refNo, interState, subtotal, discount, gstAmount, rounded.roundOff,
        total, paid, notes, nowStamp(), actor?.username ?? '');
    const purchaseId = Number(info.lastInsertRowid);

    const insertItem = conn.prepare(`INSERT INTO purchase_items
      (purchase_id, product_id, batch_id, name, batch_no, expiry, mrp, qty_units, free_units,
       rate_per_unit, disc_pct, gst_rate, taxable, gst_amount, total)
      VALUES (@purchase_id, @product_id, @batch_id, @name, @batch_no, @expiry, @mrp, @qty_units,
              @free_units, @rate_per_unit, @disc_pct, @gst_rate, @taxable, @gst_amount, @total)`);

    for (const line of lines) {
      const batchId = products.upsertBatch({
        productId: line.product_id,
        batchNo: line.batch_no,
        expiry: line.expiry,
        mrp: line.mrp,
        ratePerUnit: line.landed_cost
      });
      insertItem.run({ ...line, batch_id: batchId, purchase_id: purchaseId });
      products.moveStock(batchId, line.qty_units + line.free_units);
    }

    if (paid > 0) {
      const payMode = mode === 'Credit' ? 'Cash' : mode;
      const account = ledger.accountForMode(payMode);
      conn.prepare(`INSERT INTO payments
        (date, party_type, party_id, party_name, direction, amount, mode, account, ref_no, purchase_id, notes, created_at, created_by)
        VALUES (?, 'supplier', ?, ?, 'out', ?, ?, ?, ?, ?, 'Against purchase', ?, ?)`)
        .run(date, supplierId, supplier.name, paid, payMode, account, refNo || no, purchaseId,
          nowStamp(), actor?.username ?? '');
      ledger.post({
        date, account, direction: 'out', amount: paid, sourceType: 'purchase', sourceId: purchaseId,
        description: `Purchase ${no} — ${supplier.name}`
      });
    }

    audit.log(actor, 'purchase.create', 'purchase', purchaseId, { no, total, items: lines.length });
    return byId(purchaseId);
  });
}

function byId(id) {
  const conn = db.get();
  const purchase = conn.prepare(`SELECT p.*, s.name AS supplier_name, s.gstin AS supplier_gstin,
      s.phone AS supplier_phone, s.dl_no AS supplier_dl
    FROM purchases p LEFT JOIN suppliers s ON s.id = p.supplier_id WHERE p.id = ?`).get(Number(id));
  if (!purchase) return null;
  const items = conn.prepare('SELECT * FROM purchase_items WHERE purchase_id = ? ORDER BY id').all(purchase.id);
  return { ...purchase, items, balance: r2(purchase.total - purchase.paid), store: settings.storeProfile() };
}

function list({ from, to, supplierId = null, search = '', unpaidOnly = false, limit = 300 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('p.date >= ?'); args.push(from); }
  if (to) { where.push('p.date <= ?'); args.push(to); }
  if (supplierId) { where.push('p.supplier_id = ?'); args.push(Number(supplierId)); }
  if (unpaidOnly) where.push('p.total - p.paid > 0.01');
  if (search) {
    where.push('(p.no LIKE ? OR p.ref_no LIKE ? OR s.name LIKE ?)');
    const q = `%${search}%`;
    args.push(q, q, q);
  }
  const rows = db.get().prepare(`SELECT p.*, s.name AS supplier_name,
      (SELECT COUNT(*) FROM purchase_items pi WHERE pi.purchase_id = p.id) AS line_count
    FROM purchases p LEFT JOIN suppliers s ON s.id = p.supplier_id
    ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY p.date DESC, p.id DESC LIMIT ?`).all(...args, Math.min(Number(limit) || 300, 5000));
  const totals = rows.reduce((a, r) => ({
    count: a.count + 1,
    total: r2(a.total + r.total),
    paid: r2(a.paid + r.paid),
    due: r2(a.due + (r.total - r.paid)),
    gst: r2(a.gst + r.gst_amount)
  }), { count: 0, total: 0, paid: 0, due: 0, gst: 0 });
  return { rows, totals };
}

function remove(actor, { id, reason = '' }) {
  auth.requireRole(actor, ['admin']);
  const purchaseId = v.integer(id, 'Purchase', { required: true, min: 1 });
  return db.tx(() => {
    const conn = db.get();
    const purchase = conn.prepare('SELECT * FROM purchases WHERE id = ?').get(purchaseId);
    assert(purchase, 'That purchase no longer exists.');
    const returned = conn.prepare('SELECT COUNT(*) AS n FROM purchase_returns WHERE purchase_id = ?').get(purchaseId).n;
    assert(returned === 0, 'This purchase has a return against it. Delete the return first.');
    const items = conn.prepare('SELECT * FROM purchase_items WHERE purchase_id = ?').all(purchaseId);
    for (const it of items) {
      if (!it.batch_id) continue;
      const batch = conn.prepare('SELECT * FROM batches WHERE id = ?').get(it.batch_id);
      const back = it.qty_units + it.free_units;
      assert(batch && batch.qty_units >= back,
        `${it.name} batch ${it.batch_no} has already been sold. Cannot delete this purchase — raise a purchase return instead.`,
        'STOCK_CONSUMED');
      products.moveStock(it.batch_id, -back);
    }
    ledger.reverseSource('purchase', purchaseId);
    conn.prepare('DELETE FROM payments WHERE purchase_id = ?').run(purchaseId);
    conn.prepare('DELETE FROM purchase_items WHERE purchase_id = ?').run(purchaseId);
    conn.prepare('DELETE FROM purchases WHERE id = ?').run(purchaseId);
    audit.log(actor, 'purchase.delete', 'purchase', purchaseId, { no: purchase.no, reason });
    return { ok: true };
  });
}

/** Records a payment against a supplier bill. */
function pay(actor, { id, amount, mode = 'Cash', date = null }) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const purchaseId = v.integer(id, 'Purchase', { required: true, min: 1 });
  const value = r2(v.number(amount, 'Amount', { required: true, min: 0.01, max: 1e9 }));
  const payMode = v.oneOf(mode, 'Payment mode', ledger.MODES.filter((m) => m !== 'Credit'), 'Cash');
  const when = v.date(date, 'Date', { required: false, fallback: 'today' }) || today();
  return db.tx(() => {
    const conn = db.get();
    const purchase = conn.prepare('SELECT * FROM purchases WHERE id = ?').get(purchaseId);
    assert(purchase, 'That purchase no longer exists.');
    const due = r2(purchase.total - purchase.paid);
    assert(due > 0, 'This purchase is already fully paid.');
    assert(value <= due + 0.01, `The outstanding amount on this bill is only ₹${due.toFixed(2)}.`);
    const supplier = parties.supplierById(purchase.supplier_id);
    conn.prepare('UPDATE purchases SET paid = ? WHERE id = ?').run(r2(purchase.paid + value), purchaseId);
    const account = ledger.accountForMode(payMode);
    conn.prepare(`INSERT INTO payments
      (date, party_type, party_id, party_name, direction, amount, mode, account, ref_no, purchase_id, notes, created_at, created_by)
      VALUES (?, 'supplier', ?, ?, 'out', ?, ?, ?, ?, ?, 'Bill payment', ?, ?)`)
      .run(when, purchase.supplier_id, supplier?.name ?? '', value, payMode, account,
        purchase.ref_no || purchase.no, purchaseId, nowStamp(), actor?.username ?? '');
    ledger.post({
      date: when, account, direction: 'out', amount: value, sourceType: 'purchase', sourceId: purchaseId,
      description: `Payment for purchase ${purchase.no}`
    });
    audit.log(actor, 'purchase.pay', 'purchase', purchaseId, { amount: value, mode: payMode });
    return byId(purchaseId);
  });
}

/** Last purchase price / MRP for a medicine, prefilled during purchase entry. */
function lastRate(productId) {
  return db.get().prepare(`SELECT pi.rate_per_unit, pi.mrp, pi.disc_pct, pi.gst_rate, p.date
    FROM purchase_items pi JOIN purchases p ON p.id = pi.purchase_id
    WHERE pi.product_id = ? ORDER BY p.date DESC, pi.id DESC LIMIT 1`).get(Number(productId)) ?? null;
}

module.exports = { create, byId, list, remove, pay, lastRate };

});

  define(["core/services/reminders"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const settings = require('./settings');
const v = require('../util/validate');
const { assert } = require('../util/errors');
const { nowStamp, today, addDays } = require('../util/dates');

/**
 * Refill reminders live entirely in the local database. The app never sends
 * anything by itself — it prepares the message and hands it to WhatsApp (or
 * the clipboard) only when the operator clicks Send.
 */
function list({ status = 'pending', from = null, to = null, limit = 300 } = {}) {
  const where = [];
  const args = [];
  if (status) { where.push('r.status = ?'); args.push(status); }
  if (from) { where.push('r.due_date >= ?'); args.push(from); }
  if (to) { where.push('r.due_date <= ?'); args.push(to); }
  const rows = db.get().prepare(`SELECT r.*, c.name AS customer_name, c.phone, s.no AS invoice_no
    FROM rx_reminders r JOIN customers c ON c.id = r.customer_id
    LEFT JOIN sales s ON s.id = r.sale_id
    ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY r.due_date, r.id LIMIT ?`).all(...args, Math.min(Number(limit) || 300, 2000));
  const ref = today();
  return rows.map((r) => ({ ...r, due: r.due_date <= ref, message: composeMessage(r) }));
}

function composeMessage(reminder) {
  const template = settings.get('whatsapp_template');
  return template
    .replace(/\{name\}/g, reminder.customer_name || 'there')
    .replace(/\{store\}/g, settings.get('store_name'))
    .replace(/\{medicines\}/g, reminder.medicines || 'your regular medicines')
    .replace(/\{phone\}/g, settings.get('store_phone'))
    .replace(/\{date\}/g, reminder.due_date || '');
}

function save(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist', 'cashier']);
  const customerId = v.integer(payload.customer_id, 'Customer', { required: true, min: 1 });
  const customer = db.get().prepare('SELECT * FROM customers WHERE id = ?').get(customerId);
  assert(customer, 'That customer no longer exists.');
  const dueDate = v.date(payload.due_date, 'Due date', { required: false })
    || addDays(today(), settings.num('rx_reminder_days', 25));
  const medicines = v.str(payload.medicines, 'Medicines', { max: 300 });
  const note = v.str(payload.note, 'Note', { max: 200 });
  const id = payload.id ? v.integer(payload.id, 'Reminder', { min: 1 }) : null;
  if (id) {
    db.get().prepare('UPDATE rx_reminders SET due_date = ?, medicines = ?, note = ? WHERE id = ?')
      .run(dueDate, medicines, note, id);
    audit.log(actor, 'reminder.update', 'rx_reminder', id);
    return { id };
  }
  const info = db.get().prepare(`INSERT INTO rx_reminders (customer_id, sale_id, due_date, medicines, note, status, created_at)
    VALUES (?, ?, ?, ?, ?, 'pending', ?)`)
    .run(customerId, payload.sale_id ? Number(payload.sale_id) : null, dueDate, medicines, note, nowStamp());
  audit.log(actor, 'reminder.create', 'rx_reminder', info.lastInsertRowid);
  return { id: Number(info.lastInsertRowid) };
}

function setStatus(actor, { id, status }) {
  auth.requireRole(actor, ['admin', 'pharmacist', 'cashier']);
  const rid = v.integer(id, 'Reminder', { required: true, min: 1 });
  const next = v.oneOf(status, 'Status', ['pending', 'sent', 'done', 'cancelled'], 'sent');
  db.get().prepare('UPDATE rx_reminders SET status = ?, sent_at = ? WHERE id = ?')
    .run(next, next === 'sent' ? nowStamp() : null, rid);
  audit.log(actor, 'reminder.status', 'rx_reminder', rid, next);
  return { ok: true };
}

function remove(actor, { id }) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const rid = v.integer(id, 'Reminder', { required: true, min: 1 });
  db.get().prepare('DELETE FROM rx_reminders WHERE id = ?').run(rid);
  audit.log(actor, 'reminder.delete', 'rx_reminder', rid);
  return { ok: true };
}

/** Suggests refills from buying history for customers with no open reminder. */
function suggestions({ days = 30, limit = 40 } = {}) {
  const gap = Math.max(7, Number(days) || 30);
  return db.get().prepare(`SELECT c.id AS customer_id, c.name AS customer_name, c.phone,
      MAX(s.date) AS last_visit,
      (SELECT GROUP_CONCAT(x.name, ', ') FROM (
         SELECT DISTINCT si.name FROM sale_items si
         JOIN sales s2 ON s2.id = si.sale_id
         WHERE s2.customer_id = c.id ORDER BY si.id DESC LIMIT 4) x) AS medicines
    FROM customers c JOIN sales s ON s.customer_id = c.id
    WHERE c.active = 1 AND c.phone <> ''
      AND NOT EXISTS (SELECT 1 FROM rx_reminders r WHERE r.customer_id = c.id AND r.status = 'pending')
    GROUP BY c.id
    HAVING julianday('now') - julianday(MAX(s.date)) >= ?
    ORDER BY last_visit DESC LIMIT ?`).all(gap, Math.min(Number(limit) || 40, 200));
}

module.exports = { list, save, setStatus, remove, suggestions, composeMessage };

});

  define(["core/services/reports"], function (module, exports, require) {
'use strict';

const db = require('../db');
const ledger = require('./ledger');
const products = require('./products');
const { r2 } = require('../util/money');
const { today, monthStart, addDays } = require('../util/dates');

function period({ from, to } = {}) {
  return { from: from || monthStart(today()), to: to || today() };
}

/** Day-wise sales register with GST and margin. */
function salesRegister(params = {}) {
  const { from, to } = period(params);
  const rows = db.get().prepare(`SELECT s.date,
      COUNT(*) AS bills,
      ROUND(SUM(s.subtotal),2) AS taxable,
      ROUND(SUM(s.gst_amount),2) AS gst,
      ROUND(SUM(s.discount),2) AS discount,
      ROUND(SUM(s.total),2) AS total,
      ROUND(SUM(s.paid),2) AS collected,
      ROUND(SUM(s.subtotal - s.cost_total),2) AS profit
    FROM sales s WHERE s.date >= ? AND s.date <= ? GROUP BY s.date ORDER BY s.date`).all(from, to);
  const totals = rows.reduce((a, r) => ({
    bills: a.bills + r.bills,
    taxable: r2(a.taxable + r.taxable),
    gst: r2(a.gst + r.gst),
    discount: r2(a.discount + r.discount),
    total: r2(a.total + r.total),
    collected: r2(a.collected + r.collected),
    profit: r2(a.profit + r.profit)
  }), { bills: 0, taxable: 0, gst: 0, discount: 0, total: 0, collected: 0, profit: 0 });
  return { period: { from, to }, rows, totals };
}

function purchaseRegister(params = {}) {
  const { from, to } = period(params);
  const rows = db.get().prepare(`SELECT p.date, COUNT(*) AS bills,
      ROUND(SUM(p.subtotal),2) AS taxable, ROUND(SUM(p.gst_amount),2) AS gst,
      ROUND(SUM(p.total),2) AS total, ROUND(SUM(p.paid),2) AS paid
    FROM purchases p WHERE p.date >= ? AND p.date <= ? GROUP BY p.date ORDER BY p.date`).all(from, to);
  const totals = rows.reduce((a, r) => ({
    bills: a.bills + r.bills, taxable: r2(a.taxable + r.taxable), gst: r2(a.gst + r.gst),
    total: r2(a.total + r.total), paid: r2(a.paid + r.paid)
  }), { bills: 0, taxable: 0, gst: 0, total: 0, paid: 0 });
  return { period: { from, to }, rows, totals };
}

/** Item-wise movement: sold quantity, sales value and gross margin. */
function itemMovement(params = {}) {
  const { from, to } = period(params);
  const rows = db.get().prepare(`SELECT si.product_id, si.name,
      SUM(si.qty_units) AS units,
      ROUND(SUM(si.taxable),2) AS taxable,
      ROUND(SUM(si.total),2) AS value,
      ROUND(SUM(si.taxable - si.qty_units * si.cost_per_unit),2) AS profit,
      COUNT(DISTINCT si.sale_id) AS bills
    FROM sale_items si JOIN sales s ON s.id = si.sale_id
    WHERE s.date >= ? AND s.date <= ?
    GROUP BY si.product_id, si.name ORDER BY value DESC LIMIT 500`).all(from, to);
  const stock = new Map(products.list({ limit: 5000 }).map((p) => [p.id, p]));
  return {
    period: { from, to },
    rows: rows.map((r) => ({
      ...r,
      stock_units: stock.get(r.product_id)?.stock_units ?? 0,
      stock_label: stock.get(r.product_id)?.stock_label ?? '—',
      margin_pct: r.taxable > 0 ? r2(r.profit * 100 / r.taxable) : 0
    })),
    totals: rows.reduce((a, r) => ({
      units: a.units + r.units, value: r2(a.value + r.value), profit: r2(a.profit + r.profit)
    }), { units: 0, value: 0, profit: 0 })
  };
}

/** Current stock valuation at cost and at MRP. */
function stockValuation() {
  const rows = db.get().prepare(`SELECT p.id, p.name, p.manufacturer, p.category, p.pack_size, p.pack_label,
      p.unit_label, p.rack, p.reorder_level,
      COALESCE(SUM(b.qty_units),0) AS units,
      ROUND(COALESCE(SUM(b.qty_units * b.rate_per_unit),0),2) AS cost_value,
      ROUND(COALESCE(SUM(b.qty_units * b.mrp / NULLIF(p.pack_size,0)),0),2) AS mrp_value,
      COUNT(b.id) AS batches
    FROM products p LEFT JOIN batches b ON b.product_id = p.id AND b.qty_units > 0
    WHERE p.active = 1 GROUP BY p.id ORDER BY cost_value DESC`).all();
  const totals = rows.reduce((a, r) => ({
    units: a.units + r.units, cost_value: r2(a.cost_value + r.cost_value), mrp_value: r2(a.mrp_value + r.mrp_value)
  }), { units: 0, cost_value: 0, mrp_value: 0 });
  return { rows, totals };
}

/** Cash book for a single day — receipts, payments and closing balance. */
function dayBook({ date = today() } = {}) {
  const conn = db.get();
  const opening = (() => {
    const r = conn.prepare(`SELECT
        COALESCE(SUM(CASE WHEN direction='in' THEN amount ELSE 0 END),0) AS credit,
        COALESCE(SUM(CASE WHEN direction='out' THEN amount ELSE 0 END),0) AS debit
      FROM ledger WHERE date < ?`).get(date);
    return r2(r.credit - r.debit);
  })();
  const rows = conn.prepare('SELECT * FROM ledger WHERE date = ? ORDER BY id').all(date);
  const inflow = r2(rows.filter((r) => r.direction === 'in').reduce((s, r) => s + r.amount, 0));
  const outflow = r2(rows.filter((r) => r.direction === 'out').reduce((s, r) => s + r.amount, 0));
  return {
    date,
    opening,
    rows,
    inflow,
    outflow,
    closing: r2(opening + inflow - outflow),
    balances: ledger.balances({ upto: date }),
    sales: conn.prepare(`SELECT no, patient_name, payment_mode, total, paid FROM sales WHERE date = ? ORDER BY id`).all(date),
    expenses: conn.prepare('SELECT category, payee, amount, account FROM expenses WHERE date = ? ORDER BY id').all(date)
  };
}

/** Profit & loss for a period, built from sales margin minus expenses. */
function profitLoss(params = {}) {
  const { from, to } = period(params);
  const conn = db.get();
  const sales = conn.prepare(`SELECT ROUND(COALESCE(SUM(subtotal),0),2) AS taxable,
      ROUND(COALESCE(SUM(cost_total),0),2) AS cost, ROUND(COALESCE(SUM(total),0),2) AS gross,
      COUNT(*) AS bills FROM sales WHERE date >= ? AND date <= ?`).get(from, to);
  const returns = conn.prepare(`SELECT ROUND(COALESCE(SUM(subtotal),0),2) AS taxable
    FROM sale_returns WHERE date >= ? AND date <= ?`).get(from, to);
  const expense = conn.prepare(`SELECT category, ROUND(SUM(amount),2) AS amount FROM expenses
    WHERE date >= ? AND date <= ? GROUP BY category ORDER BY amount DESC`).all(from, to);
  const expenseTotal = r2(expense.reduce((s, e) => s + e.amount, 0));
  const commissions = conn.prepare(`SELECT ROUND(COALESCE(SUM(amount),0),2) AS amount
    FROM doctor_commissions WHERE date >= ? AND date <= ?`).get(from, to).amount;
  const grossProfit = r2(sales.taxable - returns.taxable - sales.cost);
  return {
    period: { from, to },
    sales,
    returns,
    grossProfit,
    expenses: expense,
    expenseTotal,
    commissions,
    netProfit: r2(grossProfit - expenseTotal - commissions),
    marginPct: sales.taxable > 0 ? r2(grossProfit * 100 / sales.taxable) : 0
  };
}

/** Outstanding receivables and payables, oldest first. */
function outstanding() {
  const conn = db.get();
  const receivables = conn.prepare(`SELECT s.id, s.no, s.date, s.total, s.paid,
      ROUND(s.total - s.paid, 2) AS due, COALESCE(c.name, s.patient_name, 'Walk-in') AS party,
      c.phone, CAST(julianday('now') - julianday(s.date) AS INTEGER) AS age_days
    FROM sales s LEFT JOIN customers c ON c.id = s.customer_id
    WHERE s.total - s.paid > 0.01 ORDER BY s.date`).all();
  const payables = conn.prepare(`SELECT p.id, p.no, p.ref_no, p.date, p.total, p.paid,
      ROUND(p.total - p.paid, 2) AS due, s.name AS party, s.phone,
      CAST(julianday('now') - julianday(p.date) AS INTEGER) AS age_days
    FROM purchases p LEFT JOIN suppliers s ON s.id = p.supplier_id
    WHERE p.total - p.paid > 0.01 ORDER BY p.date`).all();
  return {
    receivables,
    payables,
    totals: {
      receivable: r2(receivables.reduce((s, r) => s + r.due, 0)),
      payable: r2(payables.reduce((s, r) => s + r.due, 0))
    }
  };
}

/** Everything the dashboard needs, in one round trip. */
function dashboard({ date = today() } = {}) {
  const sales = require('./sales');
  const conn = db.get();
  const summary = sales.summary({ date });
  const expiry = products.expiryReport({ withinDays: 90 });
  const low = products.lowStockReport();
  const pendingRx = conn.prepare(`SELECT r.*, c.name AS customer_name, c.phone
    FROM rx_reminders r JOIN customers c ON c.id = r.customer_id
    WHERE r.status = 'pending' AND r.due_date <= ? ORDER BY r.due_date LIMIT 25`)
    .all(addDays(date, 3));
  const stock = stockValuation();
  const out = outstanding();
  const expensesToday = conn.prepare('SELECT ROUND(COALESCE(SUM(amount),0),2) AS total FROM expenses WHERE date = ?').get(date).total;
  return {
    ...summary,
    balances: ledger.balances(),
    expiring: expiry.filter((e) => !e.expired).slice(0, 20),
    expired: expiry.filter((e) => e.expired).slice(0, 20),
    expiringCount: expiry.filter((e) => !e.expired).length,
    expiredCount: expiry.filter((e) => e.expired).length,
    lowStock: low.slice(0, 20),
    lowStockCount: low.length,
    pendingRx,
    pendingRxCount: conn.prepare("SELECT COUNT(*) AS n FROM rx_reminders WHERE status = 'pending'").get().n,
    stockValue: stock.totals,
    outstanding: { ...summary.outstanding, ...out.totals },
    expensesToday,
    counts: {
      products: conn.prepare('SELECT COUNT(*) AS n FROM products WHERE active = 1').get().n,
      customers: conn.prepare('SELECT COUNT(*) AS n FROM customers WHERE active = 1').get().n,
      suppliers: conn.prepare('SELECT COUNT(*) AS n FROM suppliers WHERE active = 1').get().n,
      doctors: conn.prepare('SELECT COUNT(*) AS n FROM doctors WHERE active = 1').get().n
    }
  };
}

module.exports = {
  salesRegister, purchaseRegister, itemMovement, stockValuation,
  dayBook, profitLoss, outstanding, dashboard
};

});

  define(["core/services/returns"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const settings = require('./settings');
const ledger = require('./ledger');
const parties = require('./parties');
const products = require('./products');
const v = require('../util/validate');
const { assert } = require('../util/errors');
const { r2, r3, splitGst } = require('../util/money');
const { nowStamp, today } = require('../util/dates');

// --------------------------------------------------------- sales returns

/** Lines of a bill with the quantity still available to return. */
function returnableSale({ id = null, no = null }) {
  const conn = db.get();
  const sale = id
    ? conn.prepare('SELECT * FROM sales WHERE id = ?').get(Number(id))
    : conn.prepare('SELECT * FROM sales WHERE no = ?').get(String(no));
  assert(sale, 'That bill could not be found.');
  const items = conn.prepare(`SELECT si.*, p.pack_size, p.pack_label, p.unit_label
    FROM sale_items si LEFT JOIN products p ON p.id = si.product_id
    WHERE si.sale_id = ? ORDER BY si.id`).all(sale.id);
  const customer = sale.customer_id ? parties.customerById(sale.customer_id) : null;
  return {
    sale,
    customer,
    items: items.map((it) => ({ ...it, returnable_units: it.qty_units - it.returned_units }))
  };
}

function createSaleReturn(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const date = v.date(payload.date, 'Return date', { required: false, fallback: 'today' }) || today();
  const refundMode = v.oneOf(payload.refund_mode, 'Refund mode', ['Cash', 'UPI', 'Bank Transfer', 'Adjust in balance'], 'Cash');
  const notes = v.str(payload.notes, 'Reason / notes', { max: 300 });
  assert(Array.isArray(payload.items) && payload.items.length > 0, 'Select at least one item to return.');

  return db.tx(() => {
    const conn = db.get();
    const saleId = v.integer(payload.sale_id, 'Bill', { required: true, min: 1 });
    const sale = conn.prepare('SELECT * FROM sales WHERE id = ?').get(saleId);
    assert(sale, 'That bill no longer exists.');

    const lines = [];
    for (const [index, raw] of payload.items.entries()) {
      const at = `Line ${index + 1}`;
      const saleItemId = v.integer(raw.sale_item_id, `${at}: bill line`, { required: true, min: 1 });
      const item = conn.prepare('SELECT * FROM sale_items WHERE id = ? AND sale_id = ?').get(saleItemId, saleId);
      assert(item, `${at}: that line is not part of bill ${sale.no}.`);
      const qty = v.integer(raw.qty_units, `${at}: quantity`, { required: true, min: 1, max: 10000000 });
      const available = item.qty_units - item.returned_units;
      assert(qty <= available, `${at}: only ${available} of ${item.name} can still be returned.`);
      const restock = raw.restock === undefined ? 1 : v.bool(raw.restock);
      // Return value mirrors the original line, including the discount given.
      const perUnitTaxable = r3(item.qty_units > 0 ? item.taxable / item.qty_units : 0);
      const taxable = r2(perUnitTaxable * qty);
      const gst = splitGst(taxable, item.gst_rate, !!sale.inter_state);
      lines.push({
        sale_item_id: saleItemId,
        product_id: item.product_id,
        batch_id: item.batch_id,
        name: item.name,
        batch_no: item.batch_no,
        expiry: item.expiry,
        qty_units: qty,
        rate_per_unit: item.rate_per_unit,
        gst_rate: item.gst_rate,
        taxable,
        gst_amount: gst.total,
        total: r2(taxable + gst.total),
        restock
      });
    }

    const subtotal = r2(lines.reduce((s, l) => s + l.taxable, 0));
    const gstAmount = r2(lines.reduce((s, l) => s + l.gst_amount, 0));
    const total = r2(subtotal + gstAmount);
    assert(total > 0, 'The return value works out to zero — nothing to record.');

    const no = settings.nextNumber('sale_return', 'sale_return_prefix');
    const info = conn.prepare(`INSERT INTO sale_returns
      (no, date, sale_id, customer_id, subtotal, gst_amount, total, refund_mode, notes, created_at, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
      .run(no, date, saleId, sale.customer_id, subtotal, gstAmount, total, refundMode, notes,
        nowStamp(), actor?.username ?? '');
    const returnId = Number(info.lastInsertRowid);

    const insertItem = conn.prepare(`INSERT INTO sale_return_items
      (return_id, sale_item_id, product_id, batch_id, name, batch_no, expiry, qty_units,
       rate_per_unit, gst_rate, taxable, gst_amount, total, restock)
      VALUES (@return_id, @sale_item_id, @product_id, @batch_id, @name, @batch_no, @expiry, @qty_units,
              @rate_per_unit, @gst_rate, @taxable, @gst_amount, @total, @restock)`);
    for (const line of lines) {
      insertItem.run({ ...line, return_id: returnId });
      conn.prepare('UPDATE sale_items SET returned_units = returned_units + ? WHERE id = ?')
        .run(line.qty_units, line.sale_item_id);
      if (line.restock && line.batch_id) products.moveStock(line.batch_id, line.qty_units);
    }

    if (refundMode !== 'Adjust in balance') {
      const account = ledger.accountForMode(refundMode);
      conn.prepare(`INSERT INTO payments
        (date, party_type, party_id, party_name, direction, amount, mode, account, ref_no, sale_id, notes, created_at, created_by)
        VALUES (?, 'customer', ?, ?, 'out', ?, ?, ?, ?, ?, 'Sales return refund', ?, ?)`)
        .run(date, sale.customer_id, sale.patient_name || '', total, refundMode, account, no, saleId,
          nowStamp(), actor?.username ?? '');
      ledger.post({
        date, account, direction: 'out', amount: total, sourceType: 'sale_return', sourceId: returnId,
        description: `Refund on return ${no} (bill ${sale.no})`
      });
    }

    audit.log(actor, 'sale_return.create', 'sale_return', returnId, { no, total });
    return saleReturnById(returnId);
  });
}

function saleReturnById(id) {
  const conn = db.get();
  const row = conn.prepare(`SELECT r.*, s.no AS sale_no, c.name AS customer_name, c.phone AS customer_phone
    FROM sale_returns r LEFT JOIN sales s ON s.id = r.sale_id
    LEFT JOIN customers c ON c.id = r.customer_id WHERE r.id = ?`).get(Number(id));
  if (!row) return null;
  return {
    ...row,
    items: conn.prepare('SELECT * FROM sale_return_items WHERE return_id = ? ORDER BY id').all(row.id),
    store: settings.storeProfile()
  };
}

function listSaleReturns({ from, to, search = '', limit = 300 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('r.date >= ?'); args.push(from); }
  if (to) { where.push('r.date <= ?'); args.push(to); }
  if (search) { where.push('(r.no LIKE ? OR s.no LIKE ? OR c.name LIKE ?)'); args.push(`%${search}%`, `%${search}%`, `%${search}%`); }
  const rows = db.get().prepare(`SELECT r.*, s.no AS sale_no, c.name AS customer_name
    FROM sale_returns r LEFT JOIN sales s ON s.id = r.sale_id LEFT JOIN customers c ON c.id = r.customer_id
    ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY r.date DESC, r.id DESC LIMIT ?`).all(...args, Math.min(Number(limit) || 300, 5000));
  return { rows, totals: { count: rows.length, total: r2(rows.reduce((s, r) => s + r.total, 0)) } };
}

function removeSaleReturn(actor, { id }) {
  auth.requireRole(actor, ['admin']);
  const rid = v.integer(id, 'Return', { required: true, min: 1 });
  return db.tx(() => {
    const conn = db.get();
    const row = conn.prepare('SELECT * FROM sale_returns WHERE id = ?').get(rid);
    assert(row, 'That return no longer exists.');
    const items = conn.prepare('SELECT * FROM sale_return_items WHERE return_id = ?').all(rid);
    for (const it of items) {
      if (it.restock && it.batch_id) products.moveStock(it.batch_id, -it.qty_units, { allowNegative: true });
      if (it.sale_item_id) {
        conn.prepare('UPDATE sale_items SET returned_units = MAX(0, returned_units - ?) WHERE id = ?')
          .run(it.qty_units, it.sale_item_id);
      }
    }
    ledger.reverseSource('sale_return', rid);
    conn.prepare("DELETE FROM payments WHERE sale_id = ? AND notes = 'Sales return refund' AND ref_no = ?")
      .run(row.sale_id, row.no);
    conn.prepare('DELETE FROM sale_return_items WHERE return_id = ?').run(rid);
    conn.prepare('DELETE FROM sale_returns WHERE id = ?').run(rid);
    audit.log(actor, 'sale_return.delete', 'sale_return', rid, row);
    return { ok: true };
  });
}

// ------------------------------------------------------ purchase returns

function createPurchaseReturn(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  const date = v.date(payload.date, 'Return date', { required: false, fallback: 'today' }) || today();
  const reason = v.str(payload.reason, 'Reason', { max: 120 });
  const notes = v.str(payload.notes, 'Notes', { max: 300 });
  assert(Array.isArray(payload.items) && payload.items.length > 0, 'Select at least one item to return.');

  return db.tx(() => {
    const conn = db.get();
    const supplierId = v.integer(payload.supplier_id, 'Supplier', { required: true, min: 1 });
    const supplier = parties.supplierById(supplierId);
    assert(supplier, 'Select a valid supplier.');
    const purchaseId = payload.purchase_id ? v.integer(payload.purchase_id, 'Purchase', { min: 1 }) : null;

    const lines = [];
    for (const [index, raw] of payload.items.entries()) {
      const at = `Line ${index + 1}`;
      const batchId = v.integer(raw.batch_id, `${at}: batch`, { required: true, min: 1 });
      const batch = conn.prepare('SELECT b.*, p.name, p.gst_rate FROM batches b JOIN products p ON p.id = b.product_id WHERE b.id = ?').get(batchId);
      assert(batch, `${at}: that batch no longer exists.`);
      const qty = v.integer(raw.qty_units, `${at}: quantity`, { required: true, min: 1, max: 10000000 });
      assert(qty <= batch.qty_units, `${at}: only ${batch.qty_units} units of ${batch.name} (batch ${batch.batch_no}) are in stock.`);
      const rate = v.number(raw.rate_per_unit ?? batch.rate_per_unit, `${at}: rate`, { min: 0, max: 1000000 });
      const gstRate = v.number(raw.gst_rate ?? batch.gst_rate, `${at}: GST %`, { min: 0, max: 28 });
      const taxable = r2(rate * qty);
      const gst = splitGst(taxable, gstRate, false);
      lines.push({
        product_id: batch.product_id,
        batch_id: batchId,
        name: batch.name,
        batch_no: batch.batch_no,
        expiry: batch.expiry,
        qty_units: qty,
        rate_per_unit: r3(rate),
        gst_rate: gstRate,
        taxable,
        gst_amount: gst.total,
        total: r2(taxable + gst.total)
      });
    }

    const subtotal = r2(lines.reduce((s, l) => s + l.taxable, 0));
    const gstAmount = r2(lines.reduce((s, l) => s + l.gst_amount, 0));
    const total = r2(subtotal + gstAmount);
    const no = settings.nextNumber('purchase_return', 'purchase_return_prefix');
    const info = conn.prepare(`INSERT INTO purchase_returns
      (no, date, purchase_id, supplier_id, subtotal, gst_amount, total, reason, notes, created_at, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
      .run(no, date, purchaseId, supplierId, subtotal, gstAmount, total, reason, notes,
        nowStamp(), actor?.username ?? '');
    const returnId = Number(info.lastInsertRowid);
    const insertItem = conn.prepare(`INSERT INTO purchase_return_items
      (return_id, product_id, batch_id, name, batch_no, expiry, qty_units, rate_per_unit, gst_rate, taxable, gst_amount, total)
      VALUES (@return_id, @product_id, @batch_id, @name, @batch_no, @expiry, @qty_units, @rate_per_unit,
              @gst_rate, @taxable, @gst_amount, @total)`);
    for (const line of lines) {
      insertItem.run({ ...line, return_id: returnId });
      products.moveStock(line.batch_id, -line.qty_units);
    }
    audit.log(actor, 'purchase_return.create', 'purchase_return', returnId, { no, total });
    return purchaseReturnById(returnId);
  });
}

function purchaseReturnById(id) {
  const conn = db.get();
  const row = conn.prepare(`SELECT r.*, s.name AS supplier_name, p.no AS purchase_no
    FROM purchase_returns r LEFT JOIN suppliers s ON s.id = r.supplier_id
    LEFT JOIN purchases p ON p.id = r.purchase_id WHERE r.id = ?`).get(Number(id));
  if (!row) return null;
  return {
    ...row,
    items: conn.prepare('SELECT * FROM purchase_return_items WHERE return_id = ? ORDER BY id').all(row.id),
    store: settings.storeProfile()
  };
}

function listPurchaseReturns({ from, to, limit = 300 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('r.date >= ?'); args.push(from); }
  if (to) { where.push('r.date <= ?'); args.push(to); }
  const rows = db.get().prepare(`SELECT r.*, s.name AS supplier_name, p.no AS purchase_no
    FROM purchase_returns r LEFT JOIN suppliers s ON s.id = r.supplier_id
    LEFT JOIN purchases p ON p.id = r.purchase_id
    ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY r.date DESC, r.id DESC LIMIT ?`).all(...args, Math.min(Number(limit) || 300, 5000));
  return { rows, totals: { count: rows.length, total: r2(rows.reduce((s, r) => s + r.total, 0)) } };
}

function removePurchaseReturn(actor, { id }) {
  auth.requireRole(actor, ['admin']);
  const rid = v.integer(id, 'Return', { required: true, min: 1 });
  return db.tx(() => {
    const conn = db.get();
    const row = conn.prepare('SELECT * FROM purchase_returns WHERE id = ?').get(rid);
    assert(row, 'That return no longer exists.');
    for (const it of conn.prepare('SELECT * FROM purchase_return_items WHERE return_id = ?').all(rid)) {
      if (it.batch_id) products.moveStock(it.batch_id, it.qty_units);
    }
    conn.prepare('DELETE FROM purchase_return_items WHERE return_id = ?').run(rid);
    conn.prepare('DELETE FROM purchase_returns WHERE id = ?').run(rid);
    audit.log(actor, 'purchase_return.delete', 'purchase_return', rid, row);
    return { ok: true };
  });
}

module.exports = {
  returnableSale, createSaleReturn, saleReturnById, listSaleReturns, removeSaleReturn,
  createPurchaseReturn, purchaseReturnById, listPurchaseReturns, removePurchaseReturn
};

});

  define(["core/services/sales"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const settings = require('./settings');
const ledger = require('./ledger');
const parties = require('./parties');
const products = require('./products');
const v = require('../util/validate');
const { assert, fail } = require('../util/errors');
const { r2, r3, int, num, lineTotals, splitGst, roundOff } = require('../util/money');
const { nowStamp, today, isExpired, addDays } = require('../util/dates');

const PAYMENT_MODES = ['Cash', 'UPI', 'Card', 'Cheque', 'Bank Transfer', 'Credit'];

function prepareLines(rawItems, { interState, gstInclusive }) {
  assert(Array.isArray(rawItems) && rawItems.length > 0, 'Add at least one medicine to the bill.');
  assert(rawItems.length <= 200, 'A single bill can hold up to 200 lines.');
  const conn = db.get();
  const lines = [];
  for (const [index, raw] of rawItems.entries()) {
    const at = `Line ${index + 1}`;
    const productId = v.integer(raw.product_id, `${at}: medicine`, { required: true, min: 1 });
    const product = conn.prepare('SELECT * FROM products WHERE id = ?').get(productId);
    assert(product, `${at}: that medicine no longer exists.`);
    const batchId = v.integer(raw.batch_id, `${at}: batch`, { required: true, min: 1 });
    const batch = conn.prepare('SELECT * FROM batches WHERE id = ?').get(batchId);
    assert(batch, `${at}: select a batch for ${product.name}.`);
    assert(batch.product_id === productId, `${at}: that batch does not belong to ${product.name}.`);
    assert(!isExpired(batch.expiry), `${at}: batch ${batch.batch_no} of ${product.name} has expired (${batch.expiry}).`);
    const qty = v.integer(raw.qty_units, `${at}: quantity`, { required: true, min: 1, max: 1000000 });
    if (!product.allow_loose && product.pack_size > 1) {
      assert(qty % product.pack_size === 0,
        `${at}: ${product.name} cannot be sold loose — enter quantity in multiples of ${product.pack_size}.`);
    }
    const rate = v.number(raw.rate_per_unit, `${at}: rate`, { required: true, min: 0, max: 1000000 });
    const discPct = v.number(raw.disc_pct, `${at}: discount %`, { min: 0, max: 100 });
    const gstRate = v.number(raw.gst_rate ?? product.gst_rate, `${at}: GST %`, { min: 0, max: 28 });
    const t = lineTotals({ qty, rate, discPct, gstRate, interState, gstInclusive });
    lines.push({
      product_id: productId,
      batch_id: batchId,
      name: product.name,
      hsn: product.hsn,
      batch_no: batch.batch_no,
      expiry: batch.expiry,
      mrp: batch.mrp,
      qty_units: qty,
      rate_per_unit: r3(rate),
      disc_pct: discPct,
      gst_rate: gstRate,
      taxable: t.taxable,
      cgst: t.cgst,
      sgst: t.sgst,
      igst: t.igst,
      total: t.total,
      cost_per_unit: r3(batch.rate_per_unit),
      pack_size: product.pack_size,
      pack_label: product.pack_label,
      unit_label: product.unit_label
    });
  }
  return lines;
}

/**
 * Spreads a bill-level discount across lines in proportion to their taxable
 * value, then recomputes GST so the tax always matches the amount charged.
 */
function applyBillDiscount(lines, billDiscount, interState) {
  const discount = r2(billDiscount);
  const base = r2(lines.reduce((s, l) => s + l.taxable, 0));
  if (discount <= 0 || base <= 0) return { lines, applied: 0 };
  assert(discount <= base, 'The bill discount cannot be more than the bill value.');
  let allocated = 0;
  lines.forEach((line, i) => {
    const share = i === lines.length - 1
      ? r2(discount - allocated)
      : r2(discount * line.taxable / base);
    allocated = r2(allocated + share);
    const taxable = r2(line.taxable - share);
    const gst = splitGst(taxable, line.gst_rate, interState);
    line.bill_disc = share;
    line.taxable = taxable;
    line.cgst = gst.cgst;
    line.sgst = gst.sgst;
    line.igst = gst.igst;
    line.total = r2(taxable + gst.total);
  });
  return { lines, applied: discount };
}

function create(actor, payload) {
  auth.requireRole(actor, ['admin', 'pharmacist', 'cashier']);
  const date = v.date(payload.date, 'Bill date', { required: false, fallback: 'today' }) || today();
  const interState = v.bool(payload.inter_state);
  const gstInclusive = payload.price_includes_gst === undefined
    ? settings.flag('price_includes_gst')
    : Boolean(payload.price_includes_gst);
  const paymentMode = v.oneOf(payload.payment_mode, 'Payment mode', PAYMENT_MODES, 'Cash');
  const notes = v.str(payload.notes, 'Notes', { max: 300 });
  const patientName = v.str(payload.patient_name, 'Patient name', { max: 120 });
  const patientPhone = v.phone(payload.patient_phone, 'Patient phone');
  const rxNo = v.str(payload.rx_no, 'Prescription number', { max: 40 });
  const reminderDays = v.integer(payload.reminder_days, 'Refill reminder (days)', { min: 0, max: 365, fallback: 0 });

  return db.tx(() => {
    const conn = db.get();
    let customerId = payload.customer_id ? v.integer(payload.customer_id, 'Customer', { min: 1 }) : null;
    if (!customerId && payload.new_customer && String(payload.new_customer.name || '').trim()) {
      customerId = parties.saveCustomer(actor, payload.new_customer).id;
    }
    const customer = customerId ? parties.customerById(customerId) : null;
    assert(!customerId || customer, 'That customer no longer exists.');

    const doctorId = payload.doctor_id ? v.integer(payload.doctor_id, 'Doctor', { min: 1 }) : null;
    const doctor = doctorId ? conn.prepare('SELECT * FROM doctors WHERE id = ?').get(doctorId) : null;
    assert(!doctorId || doctor, 'That doctor no longer exists.');

    const lines = prepareLines(payload.items, { interState, gstInclusive });
    const billDiscount = r2(v.number(payload.bill_discount, 'Bill discount', { min: 0, max: 1e9 }));
    applyBillDiscount(lines, billDiscount, interState);

    const subtotal = r2(lines.reduce((s, l) => s + l.taxable, 0));
    const gstAmount = r2(lines.reduce((s, l) => s + l.cgst + l.sgst + l.igst, 0));
    const lineDiscount = r2(lines.reduce((s, l) => s + (l.qty_units * l.rate_per_unit * l.disc_pct / 100), 0));
    const gross = r2(subtotal + gstAmount);
    const rounded = settings.flag('round_off_invoice') ? roundOff(gross) : { total: gross, roundOff: 0 };
    const total = rounded.total;
    const costTotal = r2(lines.reduce((s, l) => s + l.qty_units * l.cost_per_unit, 0));

    let paid = r2(v.number(payload.paid, 'Amount paid', { min: 0, max: 1e9, fallback: paymentMode === 'Credit' ? 0 : total }));
    if (paymentMode === 'Credit') {
      assert(customerId, 'A credit bill needs a customer so the balance can be tracked.');
      paid = 0;
    }
    assert(paid <= total + 0.01, 'Amount paid cannot be more than the bill total.');
    if (paid < total) assert(customerId, 'A partly paid bill needs a customer so the balance can be tracked.');

    const no = settings.nextNumber('invoice', 'invoice_prefix');
    const info = conn.prepare(`INSERT INTO sales
      (no, date, customer_id, doctor_id, patient_name, patient_phone, rx_no, inter_state, subtotal,
       discount, gst_amount, round_off, total, paid, payment_mode, cost_total, notes, created_at, created_by)
      VALUES (@no, @date, @customer_id, @doctor_id, @patient_name, @patient_phone, @rx_no, @inter_state,
              @subtotal, @discount, @gst_amount, @round_off, @total, @paid, @payment_mode, @cost_total,
              @notes, @created_at, @created_by)`)
      .run({
        no,
        date,
        customer_id: customerId,
        doctor_id: doctorId,
        patient_name: patientName || customer?.name || '',
        patient_phone: patientPhone || customer?.phone || '',
        rx_no: rxNo,
        inter_state: interState,
        subtotal,
        discount: r2(lineDiscount + billDiscount),
        gst_amount: gstAmount,
        round_off: rounded.roundOff,
        total,
        paid,
        payment_mode: paymentMode,
        cost_total: costTotal,
        notes,
        created_at: nowStamp(),
        created_by: actor?.username ?? ''
      });
    const saleId = Number(info.lastInsertRowid);

    const insertItem = conn.prepare(`INSERT INTO sale_items
      (sale_id, product_id, batch_id, name, batch_no, expiry, hsn, mrp, qty_units, rate_per_unit,
       disc_pct, gst_rate, taxable, cgst, sgst, igst, total, cost_per_unit)
      VALUES (@sale_id, @product_id, @batch_id, @name, @batch_no, @expiry, @hsn, @mrp, @qty_units,
              @rate_per_unit, @disc_pct, @gst_rate, @taxable, @cgst, @sgst, @igst, @total, @cost_per_unit)`);
    for (const line of lines) {
      insertItem.run({ ...line, sale_id: saleId });
      products.moveStock(line.batch_id, -line.qty_units);
    }

    if (paid > 0) {
      const account = ledger.accountForMode(paymentMode);
      const payInfo = conn.prepare(`INSERT INTO payments
        (date, party_type, party_id, party_name, direction, amount, mode, account, ref_no, sale_id, notes, created_at, created_by)
        VALUES (?, 'customer', ?, ?, 'in', ?, ?, ?, ?, ?, ?, ?, ?)`)
        .run(date, customerId, customer?.name ?? (patientName || 'Walk-in'), paid, paymentMode, account,
          no, saleId, 'Against bill', nowStamp(), actor?.username ?? '');
      ledger.post({
        date, account, direction: 'in', amount: paid, sourceType: 'sale', sourceId: saleId,
        description: `Bill ${no}${customer ? ` — ${customer.name}` : ''}`
      });
      void payInfo;
    }

    if (doctor && doctor.commission_pct > 0) {
      const commission = r2(subtotal * doctor.commission_pct / 100);
      if (commission > 0) {
        conn.prepare(`INSERT INTO doctor_commissions (date, doctor_id, sale_id, base_amount, pct, amount, paid, created_at)
          VALUES (?, ?, ?, ?, ?, ?, 0, ?)`)
          .run(date, doctor.id, saleId, subtotal, doctor.commission_pct, commission, nowStamp());
      }
    }

    if (reminderDays > 0 && customerId) {
      conn.prepare(`INSERT INTO rx_reminders (customer_id, sale_id, due_date, medicines, note, status, created_at)
        VALUES (?, ?, ?, ?, ?, 'pending', ?)`)
        .run(customerId, saleId, addDays(date, reminderDays),
          lines.map((l) => l.name).slice(0, 6).join(', '), 'Refill reminder', nowStamp());
    }

    audit.log(actor, 'sale.create', 'sale', saleId, { no, total, items: lines.length });
    return byId(saleId);
  });
}

function byId(id) {
  const conn = db.get();
  const sale = conn.prepare(`SELECT s.*, c.name AS customer_name, c.phone AS customer_phone,
      c.address AS customer_address, c.gstin AS customer_gstin,
      d.name AS doctor_name, d.reg_no AS doctor_reg
    FROM sales s LEFT JOIN customers c ON c.id = s.customer_id
    LEFT JOIN doctors d ON d.id = s.doctor_id WHERE s.id = ?`).get(Number(id));
  if (!sale) return null;
  const items = conn.prepare(`SELECT si.*, p.pack_size, p.pack_label, p.unit_label
    FROM sale_items si LEFT JOIN products p ON p.id = si.product_id
    WHERE si.sale_id = ? ORDER BY si.id`).all(sale.id);
  const gstSummary = {};
  for (const it of items) {
    const key = String(it.gst_rate);
    const g = gstSummary[key] || { rate: it.gst_rate, taxable: 0, cgst: 0, sgst: 0, igst: 0 };
    g.taxable = r2(g.taxable + it.taxable);
    g.cgst = r2(g.cgst + it.cgst);
    g.sgst = r2(g.sgst + it.sgst);
    g.igst = r2(g.igst + it.igst);
    gstSummary[key] = g;
  }
  return {
    ...sale,
    items,
    gst_summary: Object.values(gstSummary).sort((a, b) => a.rate - b.rate),
    balance: r2(sale.total - sale.paid),
    store: settings.storeProfile()
  };
}

function byNumber(no) {
  const row = db.get().prepare('SELECT id FROM sales WHERE no = ?').get(String(no));
  return row ? byId(row.id) : null;
}

function list({ from, to, customerId = null, search = '', paymentMode = '', unpaidOnly = false, limit = 300 } = {}) {
  const where = [];
  const args = [];
  if (from) { where.push('s.date >= ?'); args.push(from); }
  if (to) { where.push('s.date <= ?'); args.push(to); }
  if (customerId) { where.push('s.customer_id = ?'); args.push(Number(customerId)); }
  if (paymentMode) { where.push('s.payment_mode = ?'); args.push(paymentMode); }
  if (unpaidOnly) where.push('s.total - s.paid > 0.01');
  if (search) {
    where.push('(s.no LIKE ? OR s.patient_name LIKE ? OR c.name LIKE ? OR s.rx_no LIKE ?)');
    const q = `%${search}%`;
    args.push(q, q, q, q);
  }
  const rows = db.get().prepare(`SELECT s.*, c.name AS customer_name, d.name AS doctor_name,
      (SELECT COUNT(*) FROM sale_items si WHERE si.sale_id = s.id) AS line_count
    FROM sales s LEFT JOIN customers c ON c.id = s.customer_id LEFT JOIN doctors d ON d.id = s.doctor_id
    ${where.length ? `WHERE ${where.join(' AND ')}` : ''}
    ORDER BY s.date DESC, s.id DESC LIMIT ?`).all(...args, Math.min(Number(limit) || 300, 5000));
  const totals = rows.reduce((a, r) => ({
    count: a.count + 1,
    total: r2(a.total + r.total),
    paid: r2(a.paid + r.paid),
    due: r2(a.due + (r.total - r.paid)),
    gst: r2(a.gst + r.gst_amount),
    profit: r2(a.profit + (r.subtotal - r.cost_total))
  }), { count: 0, total: 0, paid: 0, due: 0, gst: 0, profit: 0 });
  return { rows, totals };
}

/** Deleting a bill restores stock and removes its money trail, atomically. */
function remove(actor, { id, reason = '' }) {
  auth.requireRole(actor, ['admin']);
  const saleId = v.integer(id, 'Bill', { required: true, min: 1 });
  return db.tx(() => {
    const conn = db.get();
    const sale = conn.prepare('SELECT * FROM sales WHERE id = ?').get(saleId);
    assert(sale, 'That bill no longer exists.');
    const returned = conn.prepare('SELECT COUNT(*) AS n FROM sale_returns WHERE sale_id = ?').get(saleId).n;
    assert(returned === 0, 'This bill has a sales return against it. Delete the return first.');
    const items = conn.prepare('SELECT * FROM sale_items WHERE sale_id = ?').all(saleId);
    for (const it of items) {
      if (it.batch_id) products.moveStock(it.batch_id, it.qty_units, { allowNegative: true });
    }
    ledger.reverseSource('sale', saleId);
    conn.prepare('DELETE FROM payments WHERE sale_id = ?').run(saleId);
    conn.prepare('DELETE FROM doctor_commissions WHERE sale_id = ?').run(saleId);
    conn.prepare('DELETE FROM rx_reminders WHERE sale_id = ?').run(saleId);
    conn.prepare('DELETE FROM sale_items WHERE sale_id = ?').run(saleId);
    conn.prepare('DELETE FROM sales WHERE id = ?').run(saleId);
    audit.log(actor, 'sale.delete', 'sale', saleId, { no: sale.no, total: sale.total, reason });
    return { ok: true };
  });
}

/** Adds a receipt against an existing credit bill. */
function collect(actor, { id, amount, mode = 'Cash', date = null }) {
  auth.requireRole(actor, ['admin', 'pharmacist', 'cashier']);
  const saleId = v.integer(id, 'Bill', { required: true, min: 1 });
  const value = r2(v.number(amount, 'Amount', { required: true, min: 0.01, max: 1e9 }));
  const payMode = v.oneOf(mode, 'Payment mode', PAYMENT_MODES.filter((m) => m !== 'Credit'), 'Cash');
  const when = v.date(date, 'Date', { required: false, fallback: 'today' }) || today();
  return db.tx(() => {
    const conn = db.get();
    const sale = conn.prepare('SELECT * FROM sales WHERE id = ?').get(saleId);
    assert(sale, 'That bill no longer exists.');
    const due = r2(sale.total - sale.paid);
    assert(due > 0, 'This bill is already fully paid.');
    assert(value <= due + 0.01, `The outstanding amount on this bill is only ₹${due.toFixed(2)}.`);
    conn.prepare('UPDATE sales SET paid = ? WHERE id = ?').run(r2(sale.paid + value), saleId);
    const account = ledger.accountForMode(payMode);
    conn.prepare(`INSERT INTO payments
      (date, party_type, party_id, party_name, direction, amount, mode, account, ref_no, sale_id, notes, created_at, created_by)
      VALUES (?, 'customer', ?, ?, 'in', ?, ?, ?, ?, ?, 'Bill collection', ?, ?)`)
      .run(when, sale.customer_id, sale.patient_name || '', value, payMode, account, sale.no, saleId,
        nowStamp(), actor?.username ?? '');
    ledger.post({
      date: when, account, direction: 'in', amount: value, sourceType: 'sale', sourceId: saleId,
      description: `Collection against bill ${sale.no}`
    });
    audit.log(actor, 'sale.collect', 'sale', saleId, { amount: value, mode: payMode });
    return byId(saleId);
  });
}

/** Numbers behind the dashboard tiles. */
function summary({ date = today() } = {}) {
  const conn = db.get();
  const day = conn.prepare(`SELECT COUNT(*) AS bills, COALESCE(SUM(total),0) AS total,
      COALESCE(SUM(paid),0) AS paid, COALESCE(SUM(gst_amount),0) AS gst,
      COALESCE(SUM(subtotal - cost_total),0) AS profit
    FROM sales WHERE date = ?`).get(date);
  const month = conn.prepare(`SELECT COUNT(*) AS bills, COALESCE(SUM(total),0) AS total,
      COALESCE(SUM(subtotal - cost_total),0) AS profit
    FROM sales WHERE date >= ? AND date <= ?`).get(`${date.slice(0, 7)}-01`, date);
  const outstanding = conn.prepare(`SELECT COALESCE(SUM(total - paid),0) AS due, COUNT(*) AS bills
    FROM sales WHERE total - paid > 0.01`).get();
  const trend = conn.prepare(`SELECT date, COALESCE(SUM(total),0) AS total, COUNT(*) AS bills
    FROM sales WHERE date >= ? AND date <= ? GROUP BY date ORDER BY date`)
    .all(addDays(date, -13), date);
  const topItems = conn.prepare(`SELECT si.name, SUM(si.qty_units) AS units, ROUND(SUM(si.total),2) AS value
    FROM sale_items si JOIN sales s ON s.id = si.sale_id
    WHERE s.date >= ? AND s.date <= ? GROUP BY si.name ORDER BY value DESC LIMIT 8`)
    .all(addDays(date, -29), date);
  const paymentSplit = conn.prepare(`SELECT payment_mode, COALESCE(SUM(total),0) AS total
    FROM sales WHERE date = ? GROUP BY payment_mode`).all(date);
  return {
    date,
    day: { ...day, total: r2(day.total), paid: r2(day.paid), gst: r2(day.gst), profit: r2(day.profit) },
    month: { ...month, total: r2(month.total), profit: r2(month.profit) },
    outstanding: { due: r2(outstanding.due), bills: outstanding.bills },
    trend: trend.map((t) => ({ ...t, total: r2(t.total) })),
    topItems,
    paymentSplit
  };
}

module.exports = { PAYMENT_MODES, create, byId, byNumber, list, remove, collect, summary, prepareLines, applyBillDiscount };

});

  define(["core/services/settings"], function (module, exports, require) {
'use strict';

const db = require('../db');
const audit = require('./audit');
const auth = require('./auth');
const { DEFAULT_SETTINGS } = require('../db');
const { assert } = require('../util/errors');
const v = require('../util/validate');

function all() {
  const rows = db.get().prepare('SELECT key, value FROM settings').all();
  const out = { ...DEFAULT_SETTINGS };
  for (const r of rows) out[r.key] = r.value;
  return out;
}

function get(key, fallback = '') {
  const row = db.get().prepare('SELECT value FROM settings WHERE key = ?').get(key);
  return row ? row.value : (DEFAULT_SETTINGS[key] ?? fallback);
}

function num(key, fallback = 0) {
  const n = Number(get(key, String(fallback)));
  return Number.isFinite(n) ? n : fallback;
}

function flag(key) {
  return get(key) === '1';
}

function put(key, value) {
  db.get().prepare(`INSERT INTO settings (key, value) VALUES (?, ?)
                    ON CONFLICT(key) DO UPDATE SET value = excluded.value`).run(key, String(value ?? ''));
}

const EDITABLE = new Set(Object.keys(DEFAULT_SETTINGS));

function save(actor, patch) {
  auth.requireRole(actor, ['admin', 'pharmacist']);
  assert(patch && typeof patch === 'object', 'Nothing to save.');
  if (patch.store_gstin) v.gstin(patch.store_gstin);
  if (patch.store_phone) v.phone(patch.store_phone, 'Phone');
  const write = db.tx(() => {
    let n = 0;
    for (const [key, value] of Object.entries(patch)) {
      if (!EDITABLE.has(key)) continue;
      put(key, value);
      n += 1;
    }
    return n;
  });
  audit.log(actor, 'settings.save', 'settings', null, Object.keys(patch).join(','));
  return { saved: write, settings: all() };
}

/** Store profile block reused by invoice headers and GST reports. */
function storeProfile() {
  const s = all();
  return {
    name: s.store_name,
    tagline: s.store_tagline,
    address: s.store_address,
    city: s.store_city,
    state: s.store_state,
    pincode: s.store_pincode,
    phone: s.store_phone,
    email: s.store_email,
    gstin: s.store_gstin,
    dl_no: s.store_dl_no,
    fssai: s.store_fssai,
    currency: s.currency_symbol,
    terms: s.invoice_terms,
    footer: s.invoice_footer,
    printFormat: s.print_format
  };
}

/** Document numbers are allocated inside the caller's transaction. */
function nextNumber(counterName, prefixKey) {
  const conn = db.get();
  conn.prepare('INSERT OR IGNORE INTO counters (name, value) VALUES (?, 0)').run(counterName);
  conn.prepare('UPDATE counters SET value = value + 1 WHERE name = ?').run(counterName);
  const value = conn.prepare('SELECT value FROM counters WHERE name = ?').get(counterName).value;
  const prefix = get(prefixKey, 'DOC');
  return `${prefix}-${String(value).padStart(4, '0')}`;
}

module.exports = { all, get, num, flag, put, save, storeProfile, nextNumber };

});

